    /// Issue #474 item 2: the staging directory is checked before the first
    /// slice is read. The need is exact, so it is a refusal naming both
    /// figures, and the tape is not touched.
    #[test]
    fn read_slices_refuses_before_reading_when_staging_cannot_hold_the_slices() {
        let conn = crate::db::open_memory().unwrap();
        let data = b"a slice staging has no room for. ".repeat(10);
        let slice_id =
            seed_one_slice_fixture(&conn, "RSFULL", "rs-full", 4, &data, "completed", "staged");
        conn.execute("UPDATE stage_sets SET status = 'cleaned'", [])
            .unwrap();
        let tmp = tempfile::TempDir::new().unwrap();
        let config = staging_config(tmp.path());
        let mut store = mem_store_with_slice_at(4, &data);
        let _free = staging::FreeSpaceOverride::set(data.len() as u64 - 1);

        let err = read_slices(
            &conn,
            &config,
            "RSFULL",
            "rs-full",
            None,
            &mut store,
            site(Operation::VolumeReadSlices),
        )
        .unwrap_err()
        .to_string();

        assert!(err.contains("refusing to read"), "{err}");
        assert!(err.contains("free") && err.contains("need"), "{err}");
        assert_eq!(slice_staging_path(&conn, slice_id), None);
        assert_eq!(
            fs::read_dir(tmp.path()).unwrap().count(),
            0,
            "no directory was made for a read that never started"
        );
        // Room for exactly the bytes: reads.
        drop(_free);
        let _free = staging::FreeSpaceOverride::set(data.len() as u64);
        read_slices(
            &conn,
            &config,
            "RSFULL",
            "rs-full",
            None,
            &mut store,
            site(Operation::VolumeReadSlices),
        )
        .unwrap();
    }

    /// Issue #474 item 3: a `read-slices` that fails partway leaves nothing
    /// behind — the slice it had already read is unlinked, its
    /// `staging_path` is back to what it was, the set is not promoted and
    /// the directory it made is gone.
    #[test]
    fn a_failed_read_slices_leaves_nothing_behind() {
        let conn = crate::db::open_memory().unwrap();
        let (good_id, bad_id, set_id, mut store) =
            cleaned_set_with_a_rotted_second_slice(&conn, "RSFAIL", "rs-fail");
        // The first slice already had a path recorded (a legitimate file in
        // the original staging directory of some earlier life of the set).
        conn.execute(
            "UPDATE stage_slices SET staging_path = '/original/staging/first.age' WHERE id = ?1",
            params![good_id],
        )
        .unwrap();
        let tmp = tempfile::TempDir::new().unwrap();
        let config = staging_config(tmp.path());

        let err = read_slices(
            &conn,
            &config,
            "RSFAIL",
            "rs-fail",
            None,
            &mut store,
            site(Operation::VolumeReadSlices),
        )
        .unwrap_err()
        .to_string();

        assert!(
            err.contains("checksum mismatch reading slice at position 5"),
            "{err}"
        );
        assert_eq!(
            slice_staging_path(&conn, good_id).as_deref(),
            Some("/original/staging/first.age"),
            "a path that was there before the read is put back"
        );
        assert_eq!(slice_staging_path(&conn, bad_id), None);
        assert_eq!(stage_set_status(&conn, set_id), "cleaned");
        assert_eq!(
            fs::read_dir(tmp.path()).unwrap().count(),
            0,
            "the slice read before the failure and its directory are gone"
        );
    }

    /// The same, for the interrupt that arrives between slices.
    #[test]
    fn an_interrupted_read_slices_leaves_nothing_behind_either() {
        let conn = crate::db::open_memory().unwrap();
        let (good_id, _bad_id, set_id, mut store) =
            cleaned_set_with_a_rotted_second_slice(&conn, "RSINT", "rs-int");
        let tmp = tempfile::TempDir::new().unwrap();
        let config = staging_config(tmp.path());

        crate::signal::interrupt_this_thread(true);
        let r = read_slices(
            &conn,
            &config,
            "RSINT",
            "rs-int",
            Some(1),
            &mut store,
            site(Operation::VolumeReadSlices),
        );
        crate::signal::interrupt_this_thread(false);
        let msg = r.unwrap_err().to_string();

        assert!(
            msg.contains("--version 1"),
            "the re-run names the version: {msg}"
        );
        assert_eq!(slice_staging_path(&conn, good_id), None);
        assert_eq!(stage_set_status(&conn, set_id), "cleaned");
        assert_eq!(fs::read_dir(tmp.path()).unwrap().count(), 0);
    }

    #[test]
    fn volume_uuid_is_persisted_and_stable_not_derived_from_label() {
        // Migration 004: the uuid is an independent identifier, not a
        // restatement of the label — resume requires BOTH to match so a
        // relabelled cartridge reads as divergence (layout-session.md).
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type, capacity_bytes, status)
             VALUES ('L6-0001', 'lto', 'lto0', 'LTO-6', 1000, 'initialized')",
            [],
        )
        .unwrap();
        let id_a = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type, capacity_bytes, status)
             VALUES ('L6-0002', 'lto', 'lto0', 'LTO-6', 1000, 'initialized')",
            [],
        )
        .unwrap();
        let id_b = conn.last_insert_rowid();

        // Self-heal: fixtures that insert without a uuid still work.
        let a1 = volume_uuid(&conn, id_a).unwrap();
        let a2 = volume_uuid(&conn, id_a).unwrap();
        assert_eq!(a1, a2, "uuid must be stable once persisted");
        assert!(uuid::Uuid::parse_str(&a1).is_ok(), "must be a real uuid");

        let b = volume_uuid(&conn, id_b).unwrap();
        assert_ne!(a1, b, "distinct volumes must get distinct uuids");

        // And it is genuinely random, not a function of the label: a second
        // volume row sharing a label would still differ. (label is UNIQUE, so
        // assert the weaker observable: the uuid is not derivable from label.)
        let stored: String = conn
            .query_row(
                "SELECT uuid FROM volumes WHERE id = ?1",
                params![id_a],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored, a1, "uuid must be persisted, not recomputed");
    }

    #[test]
    fn find_staged_data_returns_units_in_name_order_with_their_slices() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('t1', 0, 'active')",
            [],
        )
        .unwrap();
        let tenant_id = conn.last_insert_rowid();

        // Inserted zeta-then-alpha, deliberately reverse-alphabetical, to
        // prove `ORDER BY u.name` (sheet §7's alphabetical next-fit) is what
        // actually orders the result, not insertion order.
        for name in ["zeta", "alpha"] {
            conn.execute(
                "INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
                 VALUES (?1, ?1, ?2, 'mtime_size', 1, 'active')",
                params![name, tenant_id],
            )
            .unwrap();
            let unit_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO snapshots (unit_id, version, status, source_path, file_count, total_size)
                 VALUES (?1, 1, 'staged', '/tmp', 1, 10)",
                params![unit_id],
            )
            .unwrap();
            let snap_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'staged', 524288)",
                params![snap_id],
            )
            .unwrap();
            let ss_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_slices
                    (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
                 VALUES (?1, 1, 10, 10, 'a', 'b', '/tmp/x')",
                params![ss_id],
            )
            .unwrap();
        }

        let units = find_staged_data(&conn, Spanning::ByPolicy(&Config::default()), None)
            .unwrap()
            .units;
        assert_eq!(units.len(), 2);
        assert_eq!(
            units[0].unit_name, "alpha",
            "ORDER BY u.name must sort alphabetically regardless of insertion order"
        );
        assert_eq!(units[1].unit_name, "zeta");
        assert_eq!(units[0].slices.len(), 1);
        assert_eq!(units[0].slices[0].sha256_encrypted, "b");
    }

    /// Issue #483: a `volume rewrite` writes only its own stage sets. The
    /// scope drops sets from the selection and leaves the order the query
    /// gives (alphabetical by unit), and `None` is every staged set.
    #[test]
    fn find_staged_data_with_a_scope_returns_only_those_sets_in_the_same_order() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('t1', 0, 'active')",
            [],
        )
        .unwrap();
        let tenant_id = conn.last_insert_rowid();
        let mut ids = std::collections::BTreeMap::new();
        for name in ["zeta", "alpha", "mid"] {
            conn.execute(
                "INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
                 VALUES (?1, ?1, ?2, 'mtime_size', 1, 'active')",
                params![name, tenant_id],
            )
            .unwrap();
            let unit_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO snapshots (unit_id, version, status, source_path, file_count, total_size)
                 VALUES (?1, 1, 'staged', '/tmp', 1, 10)",
                params![unit_id],
            )
            .unwrap();
            let snap_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'staged', 524288)",
                params![snap_id],
            )
            .unwrap();
            let ss_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_slices
                    (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
                 VALUES (?1, 1, 10, 10, 'a', 'b', '/tmp/x')",
                params![ss_id],
            )
            .unwrap();
            ids.insert(name, ss_id);
        }
        let names = |only: Option<&[i64]>| -> Vec<String> {
            find_staged_data(&conn, Spanning::ByPolicy(&Config::default()), only)
                .unwrap()
                .units
                .into_iter()
                .map(|u| u.unit_name)
                .collect()
        };
        assert_eq!(names(None), ["alpha", "mid", "zeta"]);
        assert_eq!(names(Some(&[ids["zeta"], ids["mid"]])), ["mid", "zeta"]);
        assert_eq!(names(Some(&[ids["alpha"]])), ["alpha"]);
        assert!(
            names(Some(&[])).is_empty(),
            "an empty scope selects nothing"
        );
    }

    /// Issue #483: a staged set outside the write's scope can neither be
    /// written by it nor refuse it — the whole-on-disk check is scoped too,
    /// so an unrelated broken set cannot stop a write hours after an erase.
    #[test]
    fn check_staged_slices_with_a_scope_ignores_a_set_outside_it() {
        let conn = crate::db::open_memory().unwrap();
        let tmp = tempfile::TempDir::new().unwrap();
        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('t1', 0, 'active')",
            [],
        )
        .unwrap();
        let tenant_id = conn.last_insert_rowid();
        let make = |name: &str, on_disk: bool| -> i64 {
            conn.execute(
                "INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
                 VALUES (?1, ?1, ?2, 'mtime_size', 1, 'active')",
                params![name, tenant_id],
            )
            .unwrap();
            let unit_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO snapshots (unit_id, version, status, source_path, file_count, total_size)
                 VALUES (?1, 1, 'current', '/tmp', 1, 10)",
                params![unit_id],
            )
            .unwrap();
            let snap_id = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'staged', 524288)",
                params![snap_id],
            )
            .unwrap();
            let ss_id = conn.last_insert_rowid();
            let path = tmp.path().join(format!("{name}.age"));
            if on_disk {
                std::fs::write(&path, [7u8; 10]).unwrap();
            }
            conn.execute(
                "INSERT INTO stage_slices
                    (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
                 VALUES (?1, 1, 10, 10, 'a', 'b', ?2)",
                params![ss_id, path.to_string_lossy()],
            )
            .unwrap();
            ss_id
        };
        let whole = make("whole", true);
        let broken = make("broken", false);

        let err = check_staged_slices(&conn, None).unwrap_err().to_string();
        assert!(
            err.contains("broken"),
            "unscoped, the broken set refuses: {err}"
        );
        check_staged_slices(&conn, Some(&[whole]))
            .expect("scoped to the whole set, the broken one is not this write's business");
        let err = check_staged_slices(&conn, Some(&[broken]))
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("broken.age") && !err.contains("whole.age"),
            "{err}"
        );
    }

    /// Issue #483: `compact-read` reports the stage sets it promoted and the
    /// slice files it wrote, with the `staging_path` each replaced — what
    /// `volume rewrite` re-reads from the disk and puts back if it refuses.
    #[test]
    fn compact_read_reports_the_sets_and_files_it_staged() {
        let conn = crate::db::open_memory().unwrap();
        let data = b"compact_read report fixture plaintext, repeated. ".repeat(10);
        let slice_id = seed_one_slice_fixture(
            &conn,
            "CRREPORT",
            "cr-report",
            4,
            &data,
            "completed",
            "staged",
        );
        let set_id = stage_set_of_slice(&conn, slice_id);
        conn.execute("UPDATE stage_sets SET status = 'cleaned'", [])
            .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let mut config = Config::default();
        config.staging.directory = tmp.path().to_string_lossy().into_owned();
        let mut store = mem_store_with_slice_at(4, &data);
        let report = compact_read(
            &conn,
            &config,
            "CRREPORT",
            &mut store,
            site(Operation::VolumeRewrite),
        )
        .unwrap();

        assert_eq!(report.staged_sets, vec![set_id]);
        assert_eq!(report.staged.len(), 1);
        let staged = &report.staged[0];
        assert_eq!(staged.slice_id, slice_id);
        assert_eq!(staged.stage_set_id, set_id);
        assert_eq!(staged.prior, None, "the set was released: no path before");
        assert_eq!(std::fs::read(&staged.path).unwrap(), data);
        assert!(staged.path.starts_with(tmp.path().join("compact-CRREPORT")));
        let (path, status): (Option<String>, String) = conn
            .query_row(
                "SELECT sl.staging_path, ss.status FROM stage_slices sl
                 JOIN stage_sets ss ON ss.id = sl.stage_set_id WHERE sl.id = ?1",
                params![slice_id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(path.as_deref(), Some(staged.path.to_str().unwrap()));
        assert_eq!(status, "staged");
    }

