    // --- issue #115: recorded recipients vs the CURRENT escrow ------------
    //
    // The defect these pin: `stage create` encrypts the slices, `volume
    // write` encrypts the envelopes, and the escrow recipient could be
    // registered between the two. Pre-write validation only asked "is an
    // escrow registered", so the tape sealed and verified clean with
    // 5-recipient envelopes over 4-recipient slices — the escrow key opens
    // the envelope and not the data, which is the exact failure ADR-0005
    // exists to prevent. `stage_sets.key_fingerprints` is the ONLY evidence
    // of who a staged slice was really encrypted to (an age X25519 stanza
    // carries an ephemeral share, not a recipient identity), so it is what
    // gets compared.

    /// A DB with an operator tenant (+ active key), one content tenant
    /// (+ active key), one unit/snapshot/stage_set, and no escrow yet.
    /// Returns `(conn, tenant_id, stage_set_id)`.
    fn escrow_check_fixture() -> (Connection, i64, i64) {
        let conn = crate::db::open_memory().unwrap();
        let (tenant_id, stage_set_id) = seed_escrow_check_fixture(&conn);
        (conn, tenant_id, stage_set_id)
    }

    /// [`escrow_check_fixture`]'s rows, on any connection — a file-backed
    /// `db::open` for the issue #376 tests, whose locks live beside the
    /// database file. Returns `(tenant_id, stage_set_id)`.
    fn seed_escrow_check_fixture(conn: &Connection) -> (i64, i64) {
        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('operator', 1, 'active')",
            [],
        )
        .unwrap();
        let operator_id = conn.last_insert_rowid();
        let op_key = crate::crypto::keys::generate_keypair();
        conn.execute(
            "INSERT INTO encryption_keys (tenant_id, alias, fingerprint, public_key, key_type, is_active)
             VALUES (?1, 'operator-key', ?2, ?3, 'primary', 1)",
            params![operator_id, op_key.fingerprint, op_key.public_key],
        )
        .unwrap();

        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('alpha', 0, 'active')",
            [],
        )
        .unwrap();
        let tenant_id = conn.last_insert_rowid();
        let tenant_key = crate::crypto::keys::generate_keypair();
        conn.execute(
            "INSERT INTO encryption_keys (tenant_id, alias, fingerprint, public_key, key_type, is_active)
             VALUES (?1, 'alpha-key', ?2, ?3, 'primary', 1)",
            params![tenant_id, tenant_key.fingerprint, tenant_key.public_key],
        )
        .unwrap();

        conn.execute(
            "INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
             VALUES ('u-photos', 'photos', ?1, 'mtime_size', 1, 'active')",
            params![tenant_id],
        )
        .unwrap();
        let unit_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO snapshots (unit_id, version, status, source_path, file_count, total_size)
             VALUES (?1, 1, 'staged', '/tmp/photos', 1, 10)",
            params![unit_id],
        )
        .unwrap();
        let snapshot_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'staged', 524288)",
            params![snapshot_id],
        )
        .unwrap();
        let stage_set_id = conn.last_insert_rowid();

        (tenant_id, stage_set_id)
    }

    /// Register the permanent escrow recipient (ADR-0005) on its own holder
    /// tenant, exactly as production does — public key only, the secret half
    /// never touching the DB. Mirrors `tests/mhvtl_e2e.rs`'s harness.
    /// Returns the escrow public key.
    fn register_escrow(conn: &Connection) -> String {
        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('escrow-holder', 0, 'active')",
            [],
        )
        .unwrap();
        let holder_id = conn.last_insert_rowid();
        let kp = crate::crypto::keys::generate_keypair();
        queries::insert_escrow_key(
            conn,
            holder_id,
            "test-escrow",
            &kp.fingerprint,
            &kp.public_key,
            Some("test escrow recipient (ADR-0005)"),
        )
        .unwrap();
        kp.public_key
    }

    fn set_key_fingerprints(conn: &Connection, stage_set_id: i64, json: Option<&str>) {
        conn.execute(
            "UPDATE stage_sets SET key_fingerprints = ?1 WHERE id = ?2",
            params![json, stage_set_id],
        )
        .unwrap();
    }

    /// The verdict list `assemble_session_keys` hands `validate`, for the
    /// stage sets `find_staged_data` selected.
    fn verdicts(
        conn: &Connection,
        tenant_id: i64,
        stage_set_id: i64,
    ) -> Vec<(i64, String, String)> {
        let session = assemble_session_keys(conn, &[tenant_id], &[stage_set_id]).unwrap();
        session
            .keys
            .stage_sets_lacking_escrow
            .expect("production assembly must always COMPUTE this field, never leave it None")
    }

    #[test]
    fn stage_set_staged_before_escrow_registration_is_named_by_the_assembly_path() {
        // The exact real-world ordering from the 2026-09-10 LTO-6 session:
        // stage first (4 recipients), register escrow second, write third.
        let (conn, tenant_id, stage_set_id) = escrow_check_fixture();
        let other = crate::crypto::keys::generate_keypair();
        set_key_fingerprints(
            &conn,
            stage_set_id,
            Some(&serde_json::to_string(&vec![other.public_key]).unwrap()),
        );
        register_escrow(&conn);

        let v = verdicts(&conn, tenant_id, stage_set_id);
        assert_eq!(v.len(), 1, "expected exactly one lacking stage set: {v:?}");
        assert_eq!(v[0].0, stage_set_id);
        assert_eq!(v[0].1, "photos", "the verdict must name the unit");
        assert_eq!(v[0].2, "encrypted without the current escrow recipient");
    }

    /// Issue #445: `volume write --init` asks the write's catalog-only
    /// refusals before it initialises a cartridge. The real function, over a
    /// real catalog: nothing staged, a staged slice missing from disk and a
    /// tenant with no active key each refuse, and the control — the same
    /// catalog with all of it in place — passes. It reads and writes nothing:
    /// no volume row appears, whichever way it answers.
    #[test]
    fn the_init_preflight_refuses_what_the_catalog_alone_can_and_passes_otherwise() {
        let conn = crate::db::open_memory().unwrap();
        let err = write_catalog_preflight(&conn, &Config::default(), "PF-1", false)
            .unwrap_err()
            .to_string();
        assert!(err.contains("no staged data to write"), "{err}");

        let (tenant_id, stage_set_id) = seed_escrow_check_fixture(&conn);
        let tmp = tempfile::TempDir::new().unwrap();
        let slice = tmp.path().join("p.dar.age");
        std::fs::write(&slice, b"0123456789").unwrap();
        conn.execute(
            "INSERT INTO stage_slices
                (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 10, 'a', 'b', ?2)",
            params![stage_set_id, slice.to_string_lossy()],
        )
        .unwrap();
        // No escrow registered at all: not waivable, and refused before any
        // cartridge is touched.
        for waived in [false, true] {
            let err = write_catalog_preflight(&conn, &Config::default(), "PF-1", waived)
                .unwrap_err()
                .to_string();
            assert!(
                err.contains("failed pre-write validation") && err.contains("escrow"),
                "no escrow recipient registered (waived={waived}): {err}"
            );
        }
        let escrow_pk = register_escrow(&conn);
        // A staged set encrypted without the registered escrow key: refused,
        // and waived by --allow-missing-escrow exactly as the write waives it.
        set_key_fingerprints(&conn, stage_set_id, Some("[]"));
        let err = write_catalog_preflight(&conn, &Config::default(), "PF-1", false)
            .unwrap_err()
            .to_string();
        assert!(err.contains("failed pre-write validation"), "{err}");
        write_catalog_preflight(&conn, &Config::default(), "PF-1", true)
            .expect("--allow-missing-escrow waives a set the escrow key cannot open");
        set_key_fingerprints(
            &conn,
            stage_set_id,
            Some(&serde_json::to_string(&vec![escrow_pk]).unwrap()),
        );

        // A staged slice that is not on the disk.
        std::fs::remove_file(&slice).unwrap();
        let err = write_catalog_preflight(&conn, &Config::default(), "PF-1", false)
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("p.dar.age") || err.to_lowercase().contains("missing"),
            "the staged-slice check refused: {err}"
        );
        std::fs::write(&slice, b"0123456789").unwrap();

        // A tenant whose only key is no longer active.
        conn.execute(
            "UPDATE encryption_keys SET is_active = 0 WHERE tenant_id = ?1",
            params![tenant_id],
        )
        .unwrap();
        let err = write_catalog_preflight(&conn, &Config::default(), "PF-1", false)
            .unwrap_err()
            .to_string();
        assert!(err.contains("has no active key"), "{err}");
        conn.execute(
            "UPDATE encryption_keys SET is_active = 1 WHERE tenant_id = ?1",
            params![tenant_id],
        )
        .unwrap();

        write_catalog_preflight(&conn, &Config::default(), "PF-1", false)
            .expect("with the batch, the files and the keys, it passes");
        let volumes: i64 = conn
            .query_row("SELECT COUNT(*) FROM volumes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(volumes, 0, "the pre-flight creates nothing");
    }

    #[test]
    fn stage_set_recording_the_escrow_recipient_passes() {
        let (conn, tenant_id, stage_set_id) = escrow_check_fixture();
        let escrow_pk = register_escrow(&conn);
        let other = crate::crypto::keys::generate_keypair();
        set_key_fingerprints(
            &conn,
            stage_set_id,
            Some(&serde_json::to_string(&vec![other.public_key, escrow_pk]).unwrap()),
        );

        assert!(
            verdicts(&conn, tenant_id, stage_set_id).is_empty(),
            "a recorded list containing the escrow key is the PASS case"
        );

        // ...and the Layout-level predicate agrees.
        let session = assemble_session_keys(&conn, &[tenant_id], &[stage_set_id]).unwrap();
        let layout = Layout {
            label: "ESCTEST".into(),
            volume_uuid: "u".into(),
            media_type: "LTO-6".into(),
            block_size: 512 * 1024,
            budget: CapacityBudget {
                available_bytes: 1_000_000_000,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![],
        };
        assert!(layout.validate(&session.keys, SliceCheck::Size).is_ok());
    }

    #[test]
    fn escrow_check_fails_closed_on_null_unparseable_and_unencrypted() {
        // Every one of these is a stage set whose recipient list cannot be
        // proven to contain the escrow key. None of them may be skipped:
        // "we could not tell" and "it is fine" are different answers, and
        // only one of them is safe on write-once media.
        let (conn, tenant_id, stage_set_id) = escrow_check_fixture();
        let escrow_pk = register_escrow(&conn);

        // NULL — never finalized, or a pre-#115 row.
        set_key_fingerprints(&conn, stage_set_id, None);
        let v = verdicts(&conn, tenant_id, stage_set_id);
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].2, "no recorded recipient list");

        // Not JSON at all.
        set_key_fingerprints(&conn, stage_set_id, Some("{not json"));
        let v = verdicts(&conn, tenant_id, stage_set_id);
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].2, "recipient list is unreadable");

        // Valid JSON, but not a list of recipients.
        set_key_fingerprints(&conn, stage_set_id, Some("{\"escrow\": true}"));
        let v = verdicts(&conn, tenant_id, stage_set_id);
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].2, "recipient list is unreadable");

        // encrypted = 0. The recorded list deliberately DOES contain the
        // escrow key here, so only the `encrypted` column can produce a
        // verdict — proving that column is really consulted.
        set_key_fingerprints(
            &conn,
            stage_set_id,
            Some(&serde_json::to_string(&vec![escrow_pk]).unwrap()),
        );
        conn.execute(
            "UPDATE stage_sets SET encrypted = 0 WHERE id = ?1",
            params![stage_set_id],
        )
        .unwrap();
        let v = verdicts(&conn, tenant_id, stage_set_id);
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].2, "staged with encrypted=0");
    }

    #[test]
    fn no_registered_escrow_reports_only_escrow_recipient_missing_not_every_stage_set() {
        // With no escrow at all the remedy is "register one", and
        // `EscrowRecipientMissing` says exactly that. Repeating it per stage
        // set would bury it under N copies of the WRONG remedy (re-stage).
        let (conn, tenant_id, stage_set_id) = escrow_check_fixture();
        set_key_fingerprints(&conn, stage_set_id, None);

        let session = assemble_session_keys(&conn, &[tenant_id], &[stage_set_id]).unwrap();
        assert_eq!(session.keys.escrow_recipient_present, Some(false));
        assert_eq!(
            session.keys.stage_sets_lacking_escrow,
            Some(vec![]),
            "computed (Some), but empty — the missing-escrow error covers this case"
        );
    }

    #[test]
    fn stage_set_ids_for_layout_maps_slice_entries_back_to_their_stage_sets() {
        // `volume_resume`'s half of the plumbing: by resume time `plan` has
        // already moved these rows out of status='staged', so the Layout —
        // not a re-run of `find_staged_data` — is what says which stage sets
        // this session writes.
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let mut slice_ids = Vec::new();
        for n in 1..=2 {
            conn.execute(
                "INSERT INTO stage_slices
                    (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
                 VALUES (?1, ?2, 10, 10, 'a', 'b', '/tmp/x')",
                params![stage_set_id, n],
            )
            .unwrap();
            slice_ids.push(conn.last_insert_rowid());
        }

        let layout = Layout {
            label: "RESTEST".into(),
            volume_uuid: "u".into(),
            media_type: "LTO-6".into(),
            block_size: 512 * 1024,
            budget: CapacityBudget {
                available_bytes: 1_000_000_000,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![
                LayoutEntry {
                    position: 0,
                    kind: ZoneKind::IdThunk,
                    size_bytes: Some(10),
                    sha256: None,
                    source: ContentSource::Generated,
                },
                LayoutEntry {
                    position: 4,
                    kind: ZoneKind::Slice {
                        stage_slice_id: slice_ids[0],
                    },
                    size_bytes: Some(10),
                    sha256: Some("b".into()),
                    source: ContentSource::Generated,
                },
                LayoutEntry {
                    position: 5,
                    kind: ZoneKind::Slice {
                        stage_slice_id: slice_ids[1],
                    },
                    size_bytes: Some(10),
                    sha256: Some("b".into()),
                    source: ContentSource::Generated,
                },
            ],
        };

        assert_eq!(
            stage_set_ids_for_layout(&conn, &layout).unwrap(),
            vec![stage_set_id],
            "two slices of one stage set must dedup to one id, and non-slice \
             entries must contribute nothing"
        );
    }

    /// Issue #115, the `--force` question. `force` is a parameter of exactly
    /// one thing — [`check_fresh_write_contact`], the File-0 identity check
    /// at contact — and `volume_write` runs `built.validate(&keys)` BEFORE
    /// `TapeStore::open` ever touches a device. So a stage set lacking the
    /// escrow recipient is refused with `force = true` just as loudly as
    /// without it, and no drive is contacted on the way to the refusal.
    ///
    /// This drives the real `volume_write` (not a validate-level stand-in)
    /// precisely to pin that ordering: a bogus device path is reached only
    /// if the refusal fails to fire, in which case the error names the
    /// device instead of the stage set.
    fn sle(id: i64) -> crate::volume::layout_model::LayoutError {
        crate::volume::layout_model::LayoutError::StageSetLacksEscrow {
            stage_set_id: id,
            unit: "photos".into(),
            reason: "escrow recipient absent from recorded list".into(),
        }
    }

    #[test]
    fn allow_missing_escrow_waives_only_stage_set_escrow_gaps() {
        use crate::volume::layout_model::LayoutError;
        // Without the flag, an escrow gap blocks.
        let (blocking, waived) = blocking_validation_errors(vec![sle(1)], false);
        assert_eq!(blocking.len(), 1);
        assert!(waived.is_empty());

        // With the flag, an escrow gap is waived and nothing blocks.
        let (blocking, waived) = blocking_validation_errors(vec![sle(1), sle(2)], true);
        assert!(
            blocking.is_empty(),
            "escrow gaps must be waived: {blocking:?}"
        );
        assert_eq!(waived.len(), 2, "both gaps must be reported as warnings");

        // The flag NEVER waives a hard failure sitting alongside a gap.
        let cap = LayoutError::CapacityExceeded {
            needed: 100,
            reserve: 10,
            available: 50,
        };
        let (blocking, waived) = blocking_validation_errors(vec![sle(1), cap], true);
        assert_eq!(blocking.len(), 1, "capacity must still block");
        assert!(matches!(blocking[0], LayoutError::CapacityExceeded { .. }));
        assert_eq!(waived.len(), 1);

        // The flag NEVER waives "no escrow registered at all" — that is a
        // different failure (EscrowRecipientMissing), not a per-set gap.
        let (blocking, waived) =
            blocking_validation_errors(vec![LayoutError::EscrowRecipientMissing], true);
        assert_eq!(blocking.len(), 1, "a total escrow absence must still block");
        assert!(waived.is_empty());
    }

    #[test]
    fn force_does_not_bypass_the_escrow_check_and_never_reaches_the_device() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();

        // Staged before the escrow existed: 1 unrelated recipient recorded.
        let other = crate::crypto::keys::generate_keypair();
        set_key_fingerprints(
            &conn,
            stage_set_id,
            Some(&serde_json::to_string(&vec![other.public_key]).unwrap()),
        );
        register_escrow(&conn);

        // A real staged slice on disk, so `validate`'s tri-layer L1 has
        // something valid to check and cannot be what fails.
        let tmp = tempfile::TempDir::new().unwrap();
        let slices_dir = tmp.path().join("slices");
        fs::create_dir_all(&slices_dir).unwrap();
        let content = b"encrypted slice bytes for the force test".repeat(8);
        conn.execute(
            "INSERT INTO stage_slices (stage_set_id, slice_number, size_bytes, encrypted_bytes,
                                       sha256_plain, sha256_encrypted)
             VALUES (?1, 1, ?2, ?2, ?3, ?4)",
            params![
                stage_set_id,
                content.len() as i64,
                direct_hash(b"plaintext hash is not exercised here"),
                direct_hash(&content),
            ],
        )
        .unwrap();
        let slice_id = conn.last_insert_rowid();
        let slice_path = slices_dir.join(format!("slice_{slice_id}.age"));
        fs::write(&slice_path, &content).unwrap();
        conn.execute(
            "UPDATE stage_slices SET staging_path = ?1 WHERE id = ?2",
            params![slice_path.to_string_lossy(), slice_id],
        )
        .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type, capacity_bytes, status)
             VALUES ('FORCETEST', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        let home = tmp.path().join("home");
        fs::create_dir_all(&home).unwrap();
        let paths = TapectlPaths::new(home);
        paths.ensure_dirs().unwrap();

        let staging_dir = tmp.path().join("staging");
        fs::create_dir_all(&staging_dir).unwrap();
        let mut config = Config::default();
        config.staging.directory = staging_dir.to_string_lossy().into_owned();
        // Device paths that cannot exist: reaching either one is the failure
        // this test is looking for.
        config.backends.lto.push(crate::config::LtoBackendConfig {
            name: "no-such-drive".into(),
            device_tape: "/nonexistent/tapectl-force-test-nst".into(),
            device_sg: "/nonexistent/tapectl-force-test-sg".into(),
            // Must be able to write the volume's own LTO-6 media (issue
            // #166: volume_write now checks this before the pre-write
            // validate this test is aimed at) — an unrelated mismatch here
            // would refuse earlier, for the wrong reason.
            generation: "LTO-6".into(),
            capacity_override: Some("2400G".into()),
            fill_ceiling: 0.92,
            enospc_buffer: "50M".into(),
            post_warning_bytes: None,
        });

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "FORCETEST",
            "/nonexistent/tapectl-force-test-nst",
            512 * 1024,
            true,  // --force
            false, // --allow-missing-escrow
            false, // --prewrite-hash
            false, // --full-confirm
            true,  // --yes: the host pre-flight is not under test here
        )
        .expect_err("force must not bypass pre-write validation");
        let msg = err.to_string();

        assert!(
            msg.contains("failed pre-write validation"),
            "expected the pre-flight refusal, got: {msg}"
        );
        assert!(
            msg.contains(&format!("stage set {stage_set_id}")) && msg.contains("photos"),
            "the refusal must name the offending stage set and its unit: {msg}"
        );
        assert!(
            msg.contains("encrypted without the current escrow recipient")
                && msg.contains("ADR-0005"),
            "the refusal must give the reason and the ADR: {msg}"
        );
        assert!(
            !msg.contains("tapectl-force-test-nst"),
            "validation must refuse BEFORE the tape device is opened: {msg}"
        );

        // Nothing was planned: no `writes` rows, so the operator is not left
        // with a phantom session to resume or abort.
        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(writes, 0, "a refused write must plan nothing");
    }

    /// ADR-0012 (issue #161): `volume write` must refuse every status other
    /// than `initialized` BEFORE it touches anything else -- no session
    /// check, no staged-data lookup, no MAM read/update, no binding, and
    /// (like the escrow model test above) no device contact. Modelled
    /// directly on `force_does_not_bypass_the_escrow_check_and_never_reaches_the_device`:
    /// a nonexistent device path, so reaching it at all is itself the
    /// failure this test looks for.
    ///
    /// `quarantined` is deliberately absent from this array (issue #242): it
    /// left the `status` CHECK entirely when it became a value of
    /// `observed_condition` instead. See
    /// `volume_write_refuses_an_initialized_volume_with_a_quarantined_condition`
    /// for that dimension's own regression test.
    #[test]
    fn volume_write_refuses_every_non_initialized_status_before_touching_the_device() {
        let statuses = ["sealed", "retired", "erased", "active"];
        // "Every non-`initialized` status" is the live schema's, not a copy
        // of it (issue #362: `blank`/`missing` stayed here after 026).
        let mut every_other = crate::db::live_status_check("volumes");
        every_other.retain(|s| s != "initialized");
        let mut ours: Vec<String> = statuses.iter().map(|s| s.to_string()).collect();
        ours.sort();
        assert_eq!(
            ours, every_other,
            "the non-write-target statuses the schema permits"
        );
        for status in statuses {
            let conn = crate::db::open_memory().unwrap();
            conn.execute(
                "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                      capacity_bytes, status, mam_capacity_bytes)
                 VALUES ('L6-STATUS', 'lto', 'lto0', 'LTO-6', 2500000000000, ?1, 123456)",
                params![status],
            )
            .unwrap();
            let volume_id = conn.last_insert_rowid();

            let mam_before: Option<i64> = conn
                .query_row(
                    "SELECT mam_capacity_bytes FROM volumes WHERE id = ?1",
                    params![volume_id],
                    |r| r.get(0),
                )
                .unwrap();
            let cartridge_volumes_before: i64 = conn
                .query_row("SELECT COUNT(*) FROM cartridge_volumes", [], |r| r.get(0))
                .unwrap();

            let tmp = tempfile::TempDir::new().unwrap();
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let config = Config::default();

            let err = volume_write(
                &conn,
                &paths,
                &config,
                "L6-STATUS",
                "/nonexistent/tapectl-write-target-test-nst",
                512 * 1024,
                false, // force
                false, // allow_missing_escrow
                false, // --prewrite-hash
                false, // --full-confirm
                true,  // --yes: the host pre-flight is not under test here
            )
            .unwrap_err();

            match &err {
                TapectlError::VolumeNotWriteTarget {
                    label,
                    status: got_status,
                } => {
                    assert_eq!(label, "L6-STATUS", "status {status}");
                    assert_eq!(got_status, status, "status {status}");
                }
                other => panic!("status {status}: expected VolumeNotWriteTarget, got: {other:?}"),
            }
            let msg = err.to_string();
            assert!(
                msg.contains("L6-STATUS"),
                "status {status}: message must name the label: {msg}"
            );
            assert!(
                msg.contains(status),
                "status {status}: message must name the status: {msg}"
            );
            assert!(
                msg.contains("ADR-0012"),
                "status {status}: message must cite ADR-0012: {msg}"
            );
            assert!(
                !msg.contains("tapectl-write-target-test-nst"),
                "status {status}: the device path must never be reached: {msg}"
            );

            let writes: i64 = conn
                .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
                .unwrap();
            assert_eq!(
                writes, 0,
                "status {status}: a refused write must plan nothing"
            );

            let mam_after: Option<i64> = conn
                .query_row(
                    "SELECT mam_capacity_bytes FROM volumes WHERE id = ?1",
                    params![volume_id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(
                mam_after, mam_before,
                "status {status}: mam_capacity_bytes must be untouched"
            );

            let cartridge_volumes_after: i64 = conn
                .query_row("SELECT COUNT(*) FROM cartridge_volumes", [], |r| r.get(0))
                .unwrap();
            assert_eq!(
                cartridge_volumes_after, cartridge_volumes_before,
                "status {status}: cartridge_volumes must be untouched"
            );
        }
    }

    /// THE negative control for issue #242's `is_write_target` regression
    /// (ADR-0012's 2026-09-17 amendment, point 5, "is_write_target is the
    /// trap"), driven through the real `volume_write` entry point rather
    /// than the bare predicate. Modelled on the loop test just above: a
    /// nonexistent device path, so reaching it at all is itself the
    /// failure this test looks for.
    ///
    /// Before the fix landed, this reached the device (or some later
    /// check) instead of refusing here, because `status = 'initialized'`
    /// alone used to be sufficient -- a write-path quarantine used to move
    /// `status` OFF `initialized` as a side effect of recording the
    /// quarantine, and once that side effect stopped happening (this
    /// issue's own fix), an `initialized`-but-quarantined volume would
    /// silently become writable again without this test.
    #[test]
    fn volume_write_refuses_an_initialized_volume_with_a_quarantined_condition() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status, observed_condition)
             VALUES ('L6-QCOND', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized', \
             'quarantined')",
            [],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "L6-QCOND",
            "/nonexistent/tapectl-quarantined-condition-test-nst",
            512 * 1024,
            false, // force
            false, // allow_missing_escrow
            false, // --prewrite-hash
            false, // --full-confirm
            true,  // --yes: the host pre-flight is not under test here
        )
        .unwrap_err();

        match &err {
            TapectlError::VolumeQuarantined { label } => {
                assert_eq!(label, "L6-QCOND");
            }
            other => panic!("expected VolumeQuarantined, got: {other:?}"),
        }
        let msg = err.to_string();
        assert!(
            msg.contains("L6-QCOND"),
            "message must name the label: {msg}"
        );
        assert!(
            msg.contains("ADR-0012"),
            "message must cite ADR-0012: {msg}"
        );
        assert!(
            !msg.contains("tapectl-quarantined-condition-test-nst"),
            "the device path must never be reached: {msg}"
        );

        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(writes, 0, "a refused write must plan nothing");
    }

    /// Issue #402: a staged set an interrupted `staging clean` left with
    /// one slice's path nulled — `find_staged_data` keeps the slice that
    /// still has a path, and before this the write sealed that one slice
    /// as the whole unit. Seeds a two-slice 'staged' set (`num_slices = 2`)
    /// whose second slice has no `staging_path`. `volume write` must refuse
    /// it by name, before the device is reached, with no `writes` row.
    #[test]
    fn volume_write_refuses_a_partially_cleaned_stage_set_before_touching_the_device() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let dir = tempfile::TempDir::new().unwrap();
        let present = dir.path().join("photos.1.dar.age");
        std::fs::write(&present, b"ciphertext one").unwrap();
        conn.execute(
            "UPDATE stage_sets SET num_slices = 2 WHERE id = ?1",
            params![stage_set_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO stage_slices (stage_set_id, slice_number, size_bytes, encrypted_bytes,
                                       sha256_plain, sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 14, 'p1', 'e1', ?2), (?1, 2, 10, 14, 'p2', 'e2', NULL)",
            params![stage_set_id, present.to_string_lossy()],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-GATE', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        // Positive control: the selection really does hand `build` a
        // one-slice unit — the defect this gate exists for.
        let units = find_staged_data(&conn, Spanning::ByPolicy(&Config::default()), None)
            .unwrap()
            .units;
        assert_eq!(units.len(), 1);
        assert_eq!(units[0].slices.len(), 1, "only the path-bearing slice");

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let err = volume_write(
            &conn,
            &paths,
            &Config::default(),
            "L6-GATE",
            "/nonexistent/tapectl-partial-stage-set-test-nst",
            512 * 1024,
            false, // force
            false, // allow_missing_escrow
            false, // --prewrite-hash
            false, // --full-confirm
            true,  // --yes
        )
        .unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("not whole on disk"), "{msg}");
        assert!(
            msg.contains("photos v1"),
            "names the unit and version: {msg}"
        );
        assert!(
            msg.contains("slice 2: no staged file recorded"),
            "names the slice: {msg}"
        );
        assert!(
            msg.contains("tapectl staging clean --unit photos --version 1 --force"),
            "no sealed copy exists, so the remedy is to release and re-stage: {msg}"
        );
        assert!(
            !msg.contains("tapectl-partial-stage-set-test-nst"),
            "the device must never be reached: {msg}"
        );
        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(writes, 0, "a refused write plans nothing");
    }

    /// Issue #402: every path-bearing slice must be on disk at its
    /// recorded size. One slice file is gone (the staging disk failed
    /// between copy 1 and copy 2) and another is short; both are named.
    #[test]
    fn volume_write_refuses_a_stage_set_whose_slice_files_are_missing_or_short() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let dir = tempfile::TempDir::new().unwrap();
        let gone = dir.path().join("photos.1.dar.age");
        let short = dir.path().join("photos.2.dar.age");
        std::fs::write(&short, b"short").unwrap();
        conn.execute(
            "UPDATE stage_sets SET num_slices = 2 WHERE id = ?1",
            params![stage_set_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO stage_slices (stage_set_id, slice_number, size_bytes, encrypted_bytes,
                                       sha256_plain, sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 14, 'p1', 'e1', ?2), (?1, 2, 10, 14, 'p2', 'e2', ?3)",
            params![
                stage_set_id,
                gone.to_string_lossy(),
                short.to_string_lossy()
            ],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-GATE', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let err = volume_write(
            &conn,
            &paths,
            &Config::default(),
            "L6-GATE",
            "/nonexistent/tapectl-missing-slice-test-nst",
            512 * 1024,
            false,
            false,
            false,
            false, // --full-confirm
            true,
        )
        .unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("not whole on disk"), "{msg}");
        assert!(
            msg.contains("slice 1:") && msg.contains("photos.1.dar.age"),
            "names the missing file: {msg}"
        );
        assert!(
            msg.contains("slice 2:") && msg.contains("is 5 bytes, 14 recorded"),
            "names the short file and both sizes: {msg}"
        );
        assert!(
            !msg.contains("tapectl-missing-slice-test-nst"),
            "the device must never be reached: {msg}"
        );
    }

    /// ADR-0012 amendment, issue #199: the rebuild scenario the issue was
    /// filed about. `catalog rebuild --from-volume` can attach a rebuilt
    /// row's contents to a pre-existing `initialized` volume without ever
    /// moving its status (#158 deliberately leaves an existing row's
    /// status alone) -- `rebuild::ensure_write` always inserts its
    /// `writes` row as `status = 'completed'`, which is reproduced here
    /// directly rather than by running a real rebuild. `volume write` must
    /// refuse this BEFORE touching anything else, exactly like every
    /// non-`initialized` status in the loop above: no staged-data lookup,
    /// no MAM read/update, no binding, no device contact, and (the whole
    /// point of #161's ordering) no new `writes` row.
    #[test]
    fn volume_write_refuses_an_initialized_volume_with_a_completed_write_before_touching_the_device(
    ) {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status, mam_capacity_bytes)
             VALUES ('L6-REBUILT', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized', 123456)",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status, write_verified,
                                 completed_at, notes)
             VALUES (?1, ?2, ?3, 'completed', 0, datetime('now'),
                     'rebuilt from the volume itself; never verified by a read-back')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();

        let mam_before: Option<i64> = conn
            .query_row(
                "SELECT mam_capacity_bytes FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| r.get(0),
            )
            .unwrap();
        let cartridge_volumes_before: i64 = conn
            .query_row("SELECT COUNT(*) FROM cartridge_volumes", [], |r| r.get(0))
            .unwrap();
        let writes_before: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(writes_before, 1, "the rebuilt row itself, seeded above");

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "L6-REBUILT",
            "/nonexistent/tapectl-rebuilt-write-target-test-nst",
            512 * 1024,
            false, // force
            false, // allow_missing_escrow
            false, // --prewrite-hash
            false, // --full-confirm
            true,  // --yes: the host pre-flight is not under test here
        )
        .unwrap_err();

        match &err {
            TapectlError::VolumeHasRecordedWrite { label } => {
                assert_eq!(label, "L6-REBUILT");
            }
            other => panic!("expected VolumeHasRecordedWrite, got: {other:?}"),
        }
        let msg = err.to_string();
        assert!(
            msg.contains("L6-REBUILT"),
            "message must name the label: {msg}"
        );
        assert!(
            msg.contains("ADR-0012"),
            "message must cite ADR-0012: {msg}"
        );
        assert!(
            !msg.contains("tapectl-rebuilt-write-target-test-nst"),
            "the device path must never be reached: {msg}"
        );

        let mam_after: Option<i64> = conn
            .query_row(
                "SELECT mam_capacity_bytes FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            mam_after, mam_before,
            "mam_capacity_bytes must be untouched"
        );

        let cartridge_volumes_after: i64 = conn
            .query_row("SELECT COUNT(*) FROM cartridge_volumes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            cartridge_volumes_after, cartridge_volumes_before,
            "cartridge_volumes must be untouched"
        );

        let writes_after: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            writes_after, writes_before,
            "a refused write must plan nothing -- no new `writes` row"
        );
    }

    /// ADR-0012 amendment, issue #199: the same rebuild scenario, but for
    /// `volume resume` -- an `initialized` row with a completed write
    /// attached must be named by that fact, not fall through to
    /// `nothing_to_resume`'s message (which would be confusing here: the
    /// completed row means there is nothing UNRESOLVED to resume).
    ///
    /// Since #360 (ADR-0012, 2026-09-29 later) that row is the state resume
    /// ADOPTS — a write the catalog lost — once a rebuild and a full verify
    /// after it are recorded. With no rebuild recorded the refusal names the
    /// rebuild, then the verify, before the tape moves (the device is never
    /// reached).
    #[test]
    fn volume_resume_refuses_an_initialized_volume_with_a_completed_write() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-REBUILT-R', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status, write_verified,
                                 completed_at, notes)
             VALUES (?1, ?2, ?3, 'completed', 0, datetime('now'),
                     'rebuilt from the volume itself; never verified by a read-back')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();
        let write_id = conn.last_insert_rowid();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-REBUILT-R",
            "/nonexistent/tapectl-resume-rebuilt-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();

        let msg = err.to_string();
        assert!(
            msg.contains("L6-REBUILT-R")
                && msg.contains("tapectl catalog rebuild --from-volume")
                && msg.contains("tapectl volume verify L6-REBUILT-R"),
            "the #360 refusal names the rebuild, then the verify: {msg}"
        );
        // #468: `catalog rebuild` refuses to parse without `--key`.
        crate::cli::operations::remedy_commands::assert_names_parsing_commands(
            &msg,
            &[("<operator or escrow secret key file>", "op.key")],
            &[
                "tapectl catalog rebuild --from-volume --key op.key",
                "tapectl volume verify L6-REBUILT-R",
                "tapectl volume resume L6-REBUILT-R",
            ],
        );
        assert!(
            !msg.contains("/nonexistent/tapectl-resume-rebuilt-test-nst"),
            "refused before the tape moves: {msg}"
        );
        assert!(
            !msg.contains("nothing to resume"),
            "must be refused by the recorded-write fact, not fall through to \
             nothing_to_resume: {msg}"
        );
        assert!(
            msg.contains("ADR-0012"),
            "message must cite ADR-0012: {msg}"
        );

        let write_status: String = conn
            .query_row(
                "SELECT status FROM writes WHERE id = ?1",
                params![write_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            write_status, "completed",
            "a refused resume must leave the writes row untouched"
        );
    }

    /// #360, condition 2 before the tape moves: a lost write whose rebuild
    /// IS recorded, but with no passing full verify after it, is refused
    /// naming `volume verify` — from rows alone, so the device is never
    /// reached. (The tape-side conditions are driven against a `MemStore`
    /// in `adopt_lost`'s tests.)
    #[test]
    fn volume_resume_of_a_rebuilt_lost_write_without_a_verify_names_volume_verify() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-LOST', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status, completed_at)
             VALUES (?1, ?2, ?3, 'completed', datetime('now'))",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();
        events::log_event(
            &conn,
            "volume",
            volume_id,
            Some("L6-LOST"),
            "catalog_rebuild",
            None,
            None,
            None,
            None,
            None,
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let err = volume_resume(
            &conn,
            &TapectlPaths::new(tmp.path().join("home")),
            &Config::default(),
            "L6-LOST",
            "/nonexistent/tapectl-resume-lost-test-nst",
            512 * 1024,
            false,
            false,
        )
        .unwrap_err();
        let msg = err.to_string();
        assert!(
            msg.contains("no passing full verify") && msg.contains("tapectl volume verify L6-LOST"),
            "{msg}"
        );
        assert!(
            !msg.contains("/nonexistent/tapectl-resume-lost-test-nst"),
            "refused before the tape moves: {msg}"
        );
        let status: String = conn
            .query_row(
                "SELECT status FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(status, "initialized");
    }

    /// #360: a volume with no writes rows at all is not resumable — but if
    /// its tape was sealed by a write this catalog lost, the refusal names
    /// the way back: rebuild, verify, resume.
    #[test]
    fn nothing_to_resume_with_no_sessions_names_the_lost_write_path() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-NONE', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let msg = nothing_to_resume(&conn, conn.last_insert_rowid(), "L6-NONE").to_string();
        assert!(msg.contains("tapectl volume write L6-NONE"), "{msg}");
        assert!(
            msg.contains("tapectl catalog rebuild --from-volume")
                && msg.contains("tapectl volume verify L6-NONE")
                && msg.contains("tapectl volume resume L6-NONE"),
            "{msg}"
        );
        // #468: `catalog rebuild` refuses to parse without `--key`.
        crate::cli::operations::remedy_commands::assert_names_parsing_commands(
            &msg,
            &[("<operator or escrow secret key file>", "op.key")],
            &[
                "tapectl volume write L6-NONE",
                "tapectl catalog rebuild --from-volume --key op.key",
                "tapectl volume verify L6-NONE",
                "tapectl volume resume L6-NONE",
            ],
        );
    }

    /// ADR-0012 (issue #161): an `initialized` volume must NOT be refused
    /// by status -- the whitelist admits it, and the call must reach a
    /// LATER, unrelated check (here, no staged data exists at all).
    #[test]
    fn volume_write_accepts_initialized_and_proceeds_to_the_next_check() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-INIT', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "L6-INIT",
            "/nonexistent/tapectl-init-proceeds-test-nst",
            512 * 1024,
            false,
            false,
            false,
            false, // --full-confirm
            true,
        )
        .expect_err("no staged data exists, so this must fail at a LATER check");

        assert!(
            !matches!(err, TapectlError::VolumeNotWriteTarget { .. }),
            "an initialized volume must not be refused by status: {err}"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("no staged data to write"),
            "expected the existing no-staged-data refusal, got: {msg}"
        );
    }

    // ── issue #201: `volume write` announces the staged sets it is about
    // to write ──

    fn unit_with_catalogue(
        name: &str,
        stage_set_id: i64,
        version: i64,
        catalog_path: Option<String>,
    ) -> BuildUnit {
        BuildUnit {
            stage_set_id,
            snapshot_id: stage_set_id,
            unit_name: name.to_string(),
            unit_uuid: format!("{name}-uuid"),
            tenant_id: 1,
            dar_version: None,
            dar_command: None,
            catalog_path,
            snapshot_version: version,
            slices: Vec::new(),
            span: None,
        }
    }

    /// Issue #473: a unit whose dar catalogue is not on disk (no
    /// `catalog_path`, or no `<stem>.<n>.dar` beside it) is named before the
    /// tape is touched, because `build` packs a catalogue only if it finds
    /// one; a unit that has it is not mentioned, and a clean selection says
    /// nothing at all.
    #[test]
    fn render_catalogue_warnings_names_exactly_the_units_with_no_catalogue_on_disk() {
        let dir = tempfile::tempdir().unwrap();
        let present = dir.path().join("aaaa1111_v1");
        fs::write(dir.path().join("aaaa1111_v1.1.dar"), b"catalogue").unwrap();
        let gone = dir.path().join("cccc3333_v1");
        let has = unit_with_catalogue("alpha", 1, 1, Some(present.to_string_lossy().into()));
        let none = unit_with_catalogue("beta", 2, 2, None);
        let removed = unit_with_catalogue("gamma", 3, 1, Some(gone.to_string_lossy().into()));

        assert_eq!(
            render_catalogue_warnings(std::slice::from_ref(&has)),
            "",
            "a unit with its catalogue is not mentioned"
        );
        let warning = render_catalogue_warnings(&[has, none, removed]);
        assert!(
            warning.starts_with("warning: no dar catalogue on disk"),
            "{warning}"
        );
        assert!(warning.contains("\n  beta v2 (stage set 2)\n"), "{warning}");
        assert!(
            warning.contains("\n  gamma v1 (stage set 3)\n"),
            "{warning}"
        );
        assert!(!warning.contains("alpha"), "{warning}");
        assert!(
            warning.contains("catalog rebuild --from-volume")
                && warning.contains("stage the version again"),
            "it names the way out: {warning}"
        );
    }

    /// Exact text, multi-unit multi-version — issue #201's first acceptance
    /// property. Pinned, not `contains`-checked: a silently reworded
    /// announcement is exactly the kind of drift a substring match would
    /// miss. Matches `volume plan`'s row shape (`src/cli/volume.rs`'s `Plan`
    /// arm) verbatim, minus the "x {copies}" term that does not apply to a
    /// single physical write.
    #[test]
    fn render_staged_selection_pins_exact_text_for_multi_unit_multi_version() {
        let units = vec![
            BuildUnit {
                stage_set_id: 1,
                snapshot_id: 1,
                unit_name: "alpha-collection".to_string(),
                unit_uuid: "u1".to_string(),
                tenant_id: 1,
                dar_version: None,
                dar_command: None,
                catalog_path: None,
                snapshot_version: 3,
                slices: vec![
                    BuildSlice {
                        slice_id: 1,
                        slice_number: 1,
                        size_bytes: 50 * 1024 * 1024,
                        encrypted_bytes: 50 * 1024 * 1024,
                        sha256_plain: "a".to_string(),
                        sha256_encrypted: "b".to_string(),
                        staging_path: PathBuf::from("/tmp/a1"),
                    },
                    BuildSlice {
                        slice_id: 2,
                        slice_number: 2,
                        size_bytes: 30 * 1024 * 1024,
                        encrypted_bytes: 30 * 1024 * 1024,
                        sha256_plain: "c".to_string(),
                        sha256_encrypted: "d".to_string(),
                        staging_path: PathBuf::from("/tmp/a2"),
                    },
                ],
                span: None,
            },
            BuildUnit {
                stage_set_id: 2,
                snapshot_id: 2,
                unit_name: "zeta-notes".to_string(),
                unit_uuid: "u2".to_string(),
                tenant_id: 1,
                dar_version: None,
                dar_command: None,
                catalog_path: None,
                snapshot_version: 1,
                slices: vec![BuildSlice {
                    slice_id: 3,
                    slice_number: 1,
                    size_bytes: 5 * 1024 * 1024,
                    encrypted_bytes: 5 * 1024 * 1024,
                    sha256_plain: "e".to_string(),
                    sha256_encrypted: "f".to_string(),
                    staging_path: PathBuf::from("/tmp/z1"),
                }],
                span: None,
            },
        ];

        let rendered = render_staged_selection("VOL-F", &units);
        assert_eq!(
            rendered,
            "about to write to volume \"VOL-F\":\n\
             \x20\x20alpha-collection v3: 2 slices, 80.0 MiB\n\
             \x20\x20zeta-notes v1: 1 slices, 5.0 MiB\n\
             \n\
             total: 3 slices, 85.0 MiB\n"
        );
    }

    /// Single-unit selection — issue #201's second acceptance property: no
    /// plural/grammar bug. The header names the volume, never a unit count,
    /// so there is no "1 units" to get wrong; the per-row and total lines
    /// keep `volume plan`'s own "N slices" wording unconditionally (Plan
    /// does not pluralize for N == 1 either — `src/cli/volume.rs`'s `Plan`
    /// arm prints "1 slices" the same way), so a single unit with a single
    /// slice is not special-cased into a second vocabulary.
    #[test]
    fn render_staged_selection_reads_sensibly_for_a_single_unit() {
        let units = vec![BuildUnit {
            stage_set_id: 1,
            snapshot_id: 1,
            unit_name: "solo".to_string(),
            unit_uuid: "u1".to_string(),
            tenant_id: 1,
            dar_version: None,
            dar_command: None,
            catalog_path: None,
            snapshot_version: 1,
            slices: vec![BuildSlice {
                slice_id: 1,
                slice_number: 1,
                size_bytes: 1024 * 1024,
                encrypted_bytes: 1024 * 1024,
                sha256_plain: "a".to_string(),
                sha256_encrypted: "b".to_string(),
                staging_path: PathBuf::from("/tmp/solo1"),
            }],
            span: None,
        }];

        let rendered = render_staged_selection("VOL-SOLO", &units);
        assert_eq!(
            rendered,
            "about to write to volume \"VOL-SOLO\":\n\
             \x20\x20solo v1: 1 slices, 1.0 MiB\n\
             \n\
             total: 1 slices, 1.0 MiB\n"
        );
        assert!(
            !rendered.contains("1 units"),
            "header must never carry a unit-count phrase to get wrong: {rendered}"
        );
    }

    /// Ordering proof (issue #201), the closest this suite can get without a
    /// drive: `volume_write` has no store injection (`TapeStore::open` runs
    /// unconditionally later on), so the full function cannot be exercised
    /// end-to-end here, and capturing this process's own stderr to observe
    /// `eprint!` output would need OS-level fd redirection this suite does
    /// not otherwise use. What this test DOES prove: given a non-empty
    /// staged selection, `volume_write` does not error at (or before) the
    /// announcement call site — it proceeds past `find_staged_data` and
    /// `announce_staged_selection` and fails at the NEXT step,
    /// `resolve_lto_backend` (issue #201's call site sits between those two,
    /// see the comment above `announce_staged_selection`'s call in
    /// `volume_write`). Modelled on
    /// `volume_write_accepts_initialized_and_proceeds_to_the_next_check`
    /// just above, which proves the analogous thing one check earlier.
    #[test]
    fn volume_write_with_staged_data_passes_the_announcement_and_reaches_backend_resolution() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-ANNOUNCE', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        conn.execute(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('t1', 0, 'active')",
            [],
        )
        .unwrap();
        let tenant_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
             VALUES ('announce-unit', 'announce-unit', ?1, 'mtime_size', 1, 'active')",
            params![tenant_id],
        )
        .unwrap();
        let unit_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO snapshots (unit_id, version, status, source_path, file_count, total_size)
             VALUES (?1, 1, 'staged', '/tmp', 1, 10)",
            params![unit_id],
        )
        .unwrap();
        let snap_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'staged', 524288)",
            params![snap_id],
        )
        .unwrap();
        let ss_id = conn.last_insert_rowid();
        let tmp = tempfile::TempDir::new().unwrap();
        // A real slice file at its recorded size: issue #402's on-disk
        // check runs before backend resolution.
        let slice = tmp.path().join("x.dar.age");
        std::fs::write(&slice, b"0123456789").unwrap();
        conn.execute(
            "INSERT INTO stage_slices
                (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 10, 'a', 'b', ?2)",
            params![ss_id, slice.to_string_lossy()],
        )
        .unwrap();

        let paths = TapectlPaths::new(tmp.path().join("home"));
        // No `[[backends.lto]]` configured, so `resolve_lto_backend` is the
        // very next thing that can fail — and it fails without ever naming
        // or touching a device, exactly like the fast-refusal tests above.
        let config = Config::default();

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "L6-ANNOUNCE",
            "/nonexistent/tapectl-announce-test-nst",
            512 * 1024,
            false,
            false,
            false,
            false, // --full-confirm
            true,
        )
        .expect_err("no backend is configured, so this must fail at backend resolution");

        assert!(
            matches!(err, TapectlError::Config(_)),
            "expected a Config error from resolve_lto_backend, got: {err:?}"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("no [[backends.lto]] entry"),
            "expected resolve_lto_backend's message, got: {msg}"
        );
        assert!(
            !msg.contains("no staged data"),
            "staged data was present, so the earlier refusal must not fire: {msg}"
        );

        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            writes, 0,
            "a write refused this early must still plan nothing"
        );
    }

    /// Issue #144 (ADR-0012 2026-10-07 item 26): a write whose destination
    /// is on the cartridge already holding a copy of a version it would
    /// write is refused at plan time — one cartridge is one copy, not two —
    /// from the catalog alone, before a backend, the MAM or the drive is
    /// touched (no backend is configured here, so getting past the check
    /// would fail at backend resolution instead).
    ///
    /// The fixture's two open mounts on one cartridge, the copy still
    /// sealed, are a state no tapectl path produces: every binding erases
    /// the volumes it displaces (`binding::mount_and_record`, pinned by
    /// `coverage::tests::binding_a_destination_onto_the_copys_cartridge_erases_the_copy_first`).
    /// This pins the guard against an inconsistent catalog.
    #[test]
    fn volume_write_refuses_a_second_copy_on_the_copys_own_cartridge() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute_batch(
            "INSERT INTO tenants (id, name, is_operator, status) VALUES (1, 't1', 0, 'active');
             INSERT INTO units (id, uuid, name, tenant_id, checksum_mode, encrypt, status)
                 VALUES (1, 'u-photos', 'photos', 1, 'mtime_size', 1, 'active');
             INSERT INTO snapshots (id, unit_id, version, status, source_path, file_count, total_size)
                 VALUES (1, 1, 1, 'current', '/tmp', 1, 10);
             INSERT INTO stage_sets (id, snapshot_id, status, slice_size) VALUES (1, 1, 'staged', 524288);
             INSERT INTO volumes (id, label, backend_type, backend_name, media_type, capacity_bytes, status)
                 VALUES (1, 'L6-COPY1', 'lto', 'lto0', 'LTO-6', 2500000000000, 'sealed'),
                        (2, 'L6-COPY2', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized');
             INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status) VALUES (1, 1, 1, 'completed');
             INSERT INTO cartridges (id, barcode, media_type, nominal_capacity)
                 VALUES (1, 'BC1', 'LTO-6', 2500000000000);
             INSERT INTO cartridge_volumes (cartridge_id, volume_id) VALUES (1, 1), (1, 2);",
        )
        .unwrap();
        let tmp = tempfile::TempDir::new().unwrap();
        let slice = tmp.path().join("x.dar.age");
        std::fs::write(&slice, b"0123456789").unwrap();
        conn.execute(
            "INSERT INTO stage_slices
                (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain, sha256_encrypted, staging_path)
             VALUES (1, 1, 10, 10, 'a', 'b', ?1)",
            params![slice.to_string_lossy()],
        )
        .unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));

        let err = volume_write(
            &conn,
            &paths,
            &Config::default(),
            "L6-COPY2",
            "/nonexistent/tapectl-distinct-test-nst",
            512 * 1024,
            false,
            false,
            false,
            false,
            true,
        )
        .expect_err("a second copy on one cartridge must be refused");
        let msg = err.to_string();
        assert!(
            msg.contains("cartridge \"BC1\"")
                && msg.contains("photos v1 (volume \"L6-COPY1\")")
                && msg.contains("one copy, not two"),
            "expected the distinctness refusal, got: {msg}"
        );
        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes WHERE volume_id = 2", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(writes, 0, "a refused write plans nothing");
    }

    /// ADR-0012 (issue #161, amended 2026-09-17 for issue #242): `volume
    /// resume` must refuse a quarantined volume BEFORE `rehydrate` -- named
    /// by its condition, not answered with `nothing_to_resume`'s message
    /// about `writes` rows, and the seeded `interrupted` row must be left
    /// alone (a refused resume attempts nothing).
    ///
    /// The fixture's `status` stays `initialized` deliberately: a
    /// write-path quarantine fires only on a volume that never sealed, and
    /// since issue #242 it moves `observed_condition`, never `status` --
    /// this is the realistic shape a crashed, quarantined-mid-write session
    /// leaves behind.
    #[test]
    fn volume_resume_refuses_by_status_not_by_nothing_to_resume() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status, observed_condition)
             VALUES ('L6-QUAR', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized', \
             'quarantined')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();

        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'interrupted')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();
        let write_id = conn.last_insert_rowid();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-QUAR",
            "/nonexistent/tapectl-resume-status-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();

        match &err {
            TapectlError::VolumeQuarantined { label } => {
                assert_eq!(label, "L6-QUAR");
            }
            other => panic!("expected VolumeQuarantined, got: {other:?}"),
        }
        let msg = err.to_string();
        assert!(
            !msg.contains("nothing to resume"),
            "must be refused by condition, not fall through to nothing_to_resume: {msg}"
        );
        assert!(
            msg.contains("ADR-0012"),
            "message must cite ADR-0012: {msg}"
        );

        let write_status: String = conn
            .query_row(
                "SELECT status FROM writes WHERE id = ?1",
                params![write_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            write_status, "interrupted",
            "a refused resume must leave the writes row untouched"
        );
    }

    // ---- issue #199: the resumable states must keep working ----
    //
    // ADR-0012's dated amendment ("The write target") warns that the
    // attached-rows check this issue adds must NOT disqualify a volume
    // whose `writes` rows are `planned`/`in_progress`/`interrupted` --
    // that is exactly the set `volume resume` exists to continue. Each
    // state gets its own test, per the ruling's own instruction ("it wants
    // a test per state rather than one aggregate test"), asserting the
    // SPECIFIC downstream behavior for that state rather than merely "not
    // VolumeNotWriteTarget" -- a bare negative could also pass because of
    // an unrelated early failure.
    //
    // Run on UNMODIFIED code first (before #199's fix lands) to prove these
    // three states already reach past the status guard today; they must
    // still pass unchanged once the attached-rows check is added.

    /// A `planned` row (layout validated, nothing on tape yet) must not be
    /// treated as "this volume already holds bytes" -- `nothing_to_resume`
    /// names it by its own specific message ("not an interrupted one"),
    /// which only fires if `is_write_target`'s guard let the call through.
    #[test]
    fn volume_resume_still_targets_a_volume_with_a_planned_write() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-PLANNED', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'planned')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-PLANNED",
            "/nonexistent/tapectl-resume-planned-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();

        assert!(
            !matches!(err, TapectlError::VolumeNotWriteTarget { .. }),
            "a `planned` row must not be refused as a non-write-target: {err}"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("planned") && msg.contains("not an interrupted one"),
            "must reach nothing_to_resume's planned-specific message, proving it passed \
             the write-target guard: {msg}"
        );
    }

    /// An `in_progress` row seen while resume holds the volume's lock is a
    /// session that ended after the open (issue #376: a live one would hold
    /// the lock; `open_memory` does not sweep, so the row stays
    /// `in_progress` on purpose). It must still reach `nothing_to_resume`'s
    /// own refusal for that state, not be caught by the write-target guard.
    #[test]
    fn volume_resume_still_targets_a_volume_with_an_in_progress_write() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-INPROG', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'in_progress')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-INPROG",
            "/nonexistent/tapectl-resume-inprogress-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();

        assert!(
            !matches!(err, TapectlError::VolumeNotWriteTarget { .. }),
            "an `in_progress` row must not be refused as a non-write-target: {err}"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("no process holds its lock"),
            "must reach nothing_to_resume's in_progress-specific message, proving it \
             passed the write-target guard: {msg}"
        );
    }

    /// Issue #376, the positive control for every volume-lock refusal: a
    /// file-backed catalog, a volume with an `in_progress` write, and the
    /// volume's lock held through another open file description (the kernel
    /// treats it exactly as another process's). Returns the pieces; the
    /// caller decides when the holder drops.
    fn live_session_fixture(
        tmp: &tempfile::TempDir,
    ) -> (Connection, i64, crate::staging::lock::VolumeLock) {
        let db_file = tmp.path().join("tapectl.db");
        let conn = crate::db::open(&db_file).unwrap();
        let (_tenant_id, stage_set_id) = seed_escrow_check_fixture(&conn);
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-LIVE', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'in_progress')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();
        let holder_conn = Connection::open(&db_file).unwrap();
        let holder =
            crate::staging::lock::acquire_volume(&holder_conn, volume_id, "L6-LIVE").unwrap();
        (conn, volume_id, holder)
    }

    fn write_status(conn: &Connection, volume_id: i64) -> String {
        conn.query_row(
            "SELECT status FROM writes WHERE volume_id = ?1",
            params![volume_id],
            |r| r.get(0),
        )
        .unwrap()
    }

    /// Issue #376 (a): `volume abort` against a live session is refused as
    /// a fact — `--yes` does not reach it — and the rows are untouched.
    /// Released, the same abort gets past the lock (and, with the row now
    /// swept to `interrupted` by a fresh open, proceeds to abort it).
    #[test]
    fn volume_abort_refuses_a_live_session_and_proceeds_once_released() {
        let tmp = tempfile::TempDir::new().unwrap();
        let (conn, volume_id, holder) = live_session_fixture(&tmp);

        let err = volume_abort(&conn, "L6-LIVE", true).unwrap_err();
        assert!(
            matches!(err, TapectlError::VolumeSessionLive { .. }),
            "a held lock must refuse the abort: {err}"
        );
        assert_eq!(write_status(&conn, volume_id), "in_progress");

        drop(holder);
        drop(conn);
        let conn = crate::db::open(&tmp.path().join("tapectl.db")).unwrap();
        assert_eq!(
            write_status(&conn, volume_id),
            "interrupted",
            "released, the open sweeps the crashed session"
        );
        volume_abort(&conn, "L6-LIVE", true).expect("released, the abort proceeds");
        assert_eq!(write_status(&conn, volume_id), "aborted");
    }

    /// Issue #376 (d): `volume resume` against a live session is refused by
    /// tapectl's own rule, before any device is touched (the device path
    /// here does not exist, so reaching it would be a different error).
    #[test]
    fn volume_resume_refuses_a_live_session_and_passes_the_lock_once_released() {
        let tmp = tempfile::TempDir::new().unwrap();
        let (conn, volume_id, holder) = live_session_fixture(&tmp);
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();
        let resume = |conn: &Connection| {
            volume_resume(
                conn,
                &paths,
                &config,
                "L6-LIVE",
                "/nonexistent/tapectl-resume-live-test-nst",
                512 * 1024,
                false,
                false, // --full-confirm
            )
            .unwrap_err()
        };

        let err = resume(&conn);
        assert!(
            matches!(err, TapectlError::VolumeSessionLive { .. }),
            "a held lock must refuse the resume: {err}"
        );
        assert_eq!(write_status(&conn, volume_id), "in_progress");

        drop(holder);
        let err = resume(&conn);
        assert!(
            !matches!(err, TapectlError::VolumeSessionLive { .. }),
            "released, resume must get past the lock: {err}"
        );
    }

    /// Issue #376: `volume write` holds the lock for its session, so a
    /// second one — or any other session command — is refused while it runs.
    #[test]
    fn volume_write_refuses_a_live_session() {
        let tmp = tempfile::TempDir::new().unwrap();
        let (conn, _volume_id, _holder) = live_session_fixture(&tmp);
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let err = volume_write(
            &conn,
            &paths,
            &Config::default(),
            "L6-LIVE",
            "/nonexistent/tapectl-write-live-test-nst",
            512 * 1024,
            true,
            false,
            false,
            false, // --full-confirm
            true,
        )
        .unwrap_err();
        assert!(
            matches!(err, TapectlError::VolumeSessionLive { .. }),
            "a held lock must refuse the write, even with --force: {err}"
        );
    }

    /// An `interrupted` row is the one `rehydrate` actually adopts. Without
    /// a real frozen session directory on disk this cannot rehydrate all
    /// the way through, but it must get FAR ENOUGH to fail on the missing
    /// `session_dir` (a `rehydrate`-internal error), not be turned away at
    /// the write-target guard.
    #[test]
    fn volume_resume_still_targets_a_volume_with_an_interrupted_write() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-INTR', 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        // `session_dir` left NULL on purpose: `rehydrate` treats that as
        // "predates migration 006 / cannot be resumed", which is a
        // downstream failure distinct from the write-target guard -- the
        // point of this test is which check reaches it first.
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'interrupted')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-INTR",
            "/nonexistent/tapectl-resume-interrupted-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();

        assert!(
            !matches!(err, TapectlError::VolumeNotWriteTarget { .. }),
            "an `interrupted` row must not be refused as a non-write-target: {err}"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("no recorded session directory"),
            "must reach rehydrate's own missing-session_dir failure, proving it passed \
             the write-target guard: {msg}"
        );
    }

    // ---- issue #280: resume adopts an aborted, sealed, cleared session ----
    //
    // ADR-0012's 2026-09-23 amendment. The adoption predicate itself is
    // pinned in `session::tests` against a real MemStore session; these pin
    // what `volume_resume` SAYS for each unmet condition and that an
    // adoptable state is routed through adoption rather than refused.

    /// An `initialized` volume with one `aborted` writes row, `sealed_at`
    /// as given, the given condition, and (optionally) a recorded abort an
    /// hour ago. Returns the volume id.
    fn seed_aborted_session(
        conn: &Connection,
        stage_set_id: i64,
        label: &str,
        sealed: bool,
        condition: &str,
        abort_recorded: bool,
    ) -> i64 {
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status, observed_condition, sealed_at)
             VALUES (?1, 'lto', 'lto0', 'LTO-6', 2500000000000, 'initialized', ?2,
                     CASE WHEN ?3 THEN datetime('now', '-2 hours') END)",
            params![label, condition, sealed],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'aborted')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();
        if abort_recorded {
            conn.execute(
                "INSERT INTO events (timestamp, entity_type, entity_id, entity_label, action)
                 VALUES (datetime('now', '-1 hour'), 'volume', ?1, ?2, 'write_quarantined')",
                params![volume_id, label],
            )
            .unwrap();
        }
        volume_id
    }

    fn resume_err(conn: &Connection, label: &str) -> TapectlError {
        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();
        volume_resume(
            conn,
            &paths,
            &config,
            label,
            "/nonexistent/tapectl-resume-pm280-test-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err()
    }

    /// Still quarantined: the refusal names `volume verify <label>`, not
    /// `VolumeQuarantined`'s re-initialise remedy (which would discard a
    /// sealed tape), and touches nothing.
    #[test]
    fn volume_resume_of_an_aborted_sealed_quarantined_session_names_volume_verify() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        seed_aborted_session(&conn, stage_set_id, "L6-AQ", true, "quarantined", true);

        let err = resume_err(&conn, "L6-AQ");
        assert!(
            !matches!(err, TapectlError::VolumeQuarantined { .. }),
            "must not offer the re-initialise remedy for a sealed aborted session: {err}"
        );
        let msg = err.to_string();
        assert!(msg.contains("tapectl volume verify L6-AQ"), "{msg}");
        assert!(
            msg.contains("\"quarantined\""),
            "must name the condition: {msg}"
        );
        let status: String = conn
            .query_row(
                "SELECT status FROM writes WHERE volume_id = (SELECT id FROM volumes WHERE label = 'L6-AQ')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(status, "aborted", "a refused resume touches nothing");
    }

    /// Condition ok but no passing full verify recorded after the abort:
    /// the refusal names the abort time and `volume verify <label>`.
    #[test]
    fn volume_resume_of_an_aborted_sealed_session_without_a_later_verify_names_volume_verify() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        seed_aborted_session(&conn, stage_set_id, "L6-ANV", true, "ok", true);

        let msg = resume_err(&conn, "L6-ANV").to_string();
        assert!(msg.contains("no passing FULL verify"), "{msg}");
        assert!(msg.contains("tapectl volume verify L6-ANV"), "{msg}");
    }

    /// No recorded abort: refused rather than guessed, and no command is
    /// offered as a resolution because none resolves it.
    #[test]
    fn volume_resume_of_an_aborted_sealed_session_with_no_recorded_abort_refuses() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        seed_aborted_session(&conn, stage_set_id, "L6-ANR", true, "ok", false);

        let msg = resume_err(&conn, "L6-ANR").to_string();
        assert!(msg.contains("no event records WHEN"), "{msg}");
        assert!(!msg.contains("tapectl volume resume"), "{msg}");
    }

    /// Never sealed: today's refusal, now saying why.
    #[test]
    fn volume_resume_of_an_unsealed_aborted_session_says_it_is_never_resumable() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        seed_aborted_session(&conn, stage_set_id, "L6-AUS", false, "ok", true);

        let msg = resume_err(&conn, "L6-AUS").to_string();
        assert!(msg.contains("`volumes.sealed_at` is empty"), "{msg}");
        assert!(msg.contains("never resumable"), "{msg}");
        assert!(msg.contains("tapectl volume write L6-AUS"), "{msg}");
    }

    /// Every condition met: `volume_resume` routes the session through
    /// adoption (reaching `adopt_aborted`'s rehydration, which fails here
    /// only because this SQL fixture has no frozen session directory) —
    /// never through a refusal.
    #[test]
    fn volume_resume_routes_an_adoptable_aborted_session_through_adoption() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let volume_id = seed_aborted_session(&conn, stage_set_id, "L6-ADO", true, "ok", true);
        conn.execute(
            "INSERT INTO verification_sessions
                (volume_id, started_at, completed_at, verify_type, outcome)
             VALUES (?1, datetime('now'), datetime('now'), 'full', 'passed')",
            params![volume_id],
        )
        .unwrap();

        let msg = resume_err(&conn, "L6-ADO").to_string();
        assert!(
            msg.contains("aborted write") && msg.contains("no recorded session directory"),
            "must reach adoption's own rehydration, not a refusal: {msg}"
        );
    }

    // ---- issue #166: the drive/medium refusal at every write contact ----

    /// `volume_write` never re-checked the drive against the medium after
    /// `volume_init` — a volume initialised on one drive could be written
    /// from a different one, failing loudly on the drive's first physical
    /// write instead of refusing here, free, before the store is ever
    /// opened.
    ///
    /// The backend's generation (LTO-8) cannot write the volume's recorded
    /// generation (LTO-6); the device is nonexistent, so `detect` finds
    /// nothing and the check falls back to the volume's own row — the same
    /// cannot-see-cannot-refuse rule `check_loaded_generation` already
    /// follows. `force` changes nothing: `check_drive_can_write` has no
    /// `force` parameter at all (ADR-0010 decision 2, ADR-0008 Tier 3). And
    /// the refusal fires before `bind_late`, before the session directory,
    /// before `build()` — nothing progresses at all (issue #154's
    /// ordering).
    #[test]
    fn volume_write_refuses_a_drive_that_cannot_write_the_recorded_generation_before_bind_late() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let tmp = tempfile::TempDir::new().unwrap();
        // A real 10-byte slice file: issue #402's on-disk check runs before
        // the generation check this test is about.
        let slice = tmp.path().join("tapectl-gencheck-slice.dar.age");
        std::fs::write(&slice, b"0123456789").unwrap();
        conn.execute(
            "INSERT INTO stage_slices
                (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain,
                 sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 10, 'p', 'e', ?2)",
            params![stage_set_id, slice.to_string_lossy()],
        )
        .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-GENCHK', 'lto', 'lto8', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();

        let mut config = Config::default();
        config.staging.directory = tmp.path().join("staging").to_string_lossy().into_owned();
        config.backends.lto.push(crate::config::LtoBackendConfig {
            name: "lto8".into(),
            device_tape: "/nonexistent/tapectl-gencheck-nst".into(),
            device_sg: "/nonexistent/tapectl-gencheck-sg".into(),
            generation: "LTO-8".into(),
            capacity_override: None,
            fill_ceiling: 1.0,
            enospc_buffer: "0".into(),
            post_warning_bytes: None,
        });
        let paths = TapectlPaths::new(tmp.path().join("home"));

        for force in [false, true] {
            let err = volume_write(
                &conn,
                &paths,
                &config,
                "L6-GENCHK",
                "/nonexistent/tapectl-gencheck-nst",
                512 * 1024,
                force,
                false,
                false,
                false, // --full-confirm
                true,
            )
            .unwrap_err();
            let msg = err.to_string();
            assert!(msg.contains("cannot write LTO-6"), "{msg}");
            assert!(msg.contains("physical"), "{msg}");
            assert!(msg.contains("--force does not override it"), "{msg}");
            assert!(msg.contains("[[backends.lto]]"), "{msg}");
        }

        // Ordering (issue #154): the refusal ran before `bind_late`, before
        // the session directory / `build()` — nothing progressed at all.
        let writes: i64 = conn
            .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            writes, 0,
            "no write session may exist after a refused write"
        );
        let bindings: i64 = conn
            .query_row("SELECT COUNT(*) FROM cartridge_volumes", [], |r| r.get(0))
            .unwrap();
        assert_eq!(bindings, 0, "a refused write must displace nothing");
        assert!(
            !tmp.path().join("staging").join("sessions").exists(),
            "the session directory must never be created for a refused write"
        );
    }

    /// `volume_resume` never checked the drive against the medium at all.
    /// Same refusal as `volume_write`'s test above, reached via a manually
    /// assembled interrupted session: `InterruptedSession::rehydrate` only
    /// reads the `writes`/`write_positions` rows and the frozen
    /// `layout.json` sidecar, never re-derives a Layout, so a hand-built
    /// `Layout` (mirroring
    /// `stage_set_ids_for_layout_maps_slice_entries_back_to_their_stage_sets`'s
    /// fixture) is enough to reach `volume_resume`'s new check without a
    /// real prior write.
    #[test]
    fn volume_resume_refuses_a_drive_that_cannot_write_the_recorded_generation() {
        let (conn, tenant_id, stage_set_id) = escrow_check_fixture();

        conn.execute(
            "INSERT INTO stage_slices
                (stage_set_id, slice_number, size_bytes, encrypted_bytes, sha256_plain,
                 sha256_encrypted, staging_path)
             VALUES (?1, 1, 10, 10, 'p', 'e',
                     '/nonexistent/tapectl-resume-gencheck-slice.dar.age')",
            params![stage_set_id],
        )
        .unwrap();
        let slice_id = conn.last_insert_rowid();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-RESUMEGEN', 'lto', 'lto8', 'LTO-6', 2500000000000, 'initialized')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();

        let session_dir = tempfile::TempDir::new().unwrap();
        let layout = Layout {
            label: "L6-RESUMEGEN".into(),
            volume_uuid: "u".into(),
            media_type: "LTO-6".into(),
            block_size: 512 * 1024,
            budget: CapacityBudget {
                available_bytes: 1_000_000_000,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![
                LayoutEntry {
                    position: 0,
                    kind: ZoneKind::IdThunk,
                    size_bytes: Some(10),
                    sha256: None,
                    source: ContentSource::Generated,
                },
                LayoutEntry {
                    position: 1,
                    kind: ZoneKind::TenantEnvelope { tenant_id },
                    size_bytes: Some(10),
                    sha256: None,
                    source: ContentSource::Generated,
                },
                LayoutEntry {
                    position: 4,
                    kind: ZoneKind::Slice {
                        stage_slice_id: slice_id,
                    },
                    size_bytes: Some(10),
                    sha256: Some("e".into()),
                    source: ContentSource::Generated,
                },
            ],
        };
        let json = serde_json::to_vec_pretty(&layout).unwrap();
        std::fs::write(
            session_dir
                .path()
                .join(crate::volume::build::LAYOUT_SIDECAR),
            json,
        )
        .unwrap();

        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status, session_dir)
             VALUES (?1, ?2, ?3, 'interrupted', ?4)",
            params![
                stage_set_id,
                snapshot_id,
                volume_id,
                session_dir.path().to_string_lossy(),
            ],
        )
        .unwrap();
        let write_id = conn.last_insert_rowid();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let mut config = Config::default();
        config.backends.lto.push(crate::config::LtoBackendConfig {
            name: "lto8".into(),
            device_tape: "/nonexistent/tapectl-resume-gencheck-nst".into(),
            device_sg: "/nonexistent/tapectl-resume-gencheck-sg".into(),
            generation: "LTO-8".into(),
            capacity_override: None,
            fill_ceiling: 1.0,
            enospc_buffer: "0".into(),
            post_warning_bytes: None,
        });

        let err = volume_resume(
            &conn,
            &paths,
            &config,
            "L6-RESUMEGEN",
            "/nonexistent/tapectl-resume-gencheck-nst",
            512 * 1024,
            false,
            false, // --full-confirm
        )
        .unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("cannot write LTO-6"), "{msg}");
        assert!(msg.contains("physical"), "{msg}");

        // Nothing progressed: the interrupted session is untouched (never
        // even reached `TapeStore::open`, let alone `session.resume`).
        let write_status: String = conn
            .query_row(
                "SELECT status FROM writes WHERE id = ?1",
                params![write_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(write_status, "interrupted");
    }

    /// ADR-0012 / issue #161, fix item 3: the status guard runs BEFORE the
    /// unresolved-write-session check, and this pins that ORDER rather than
    /// merely the guard's existence.
    ///
    /// The item-7 loop above cannot pin it: none of its fixtures seed a
    /// `writes` row, so `find_staged_data`'s "no staged data" refusal would
    /// have fired anyway whichever order the two checks ran in. Here the
    /// volume is BOTH non-initialized AND carries an `interrupted` session,
    /// so exactly one of the two refusals can win and the winner names the
    /// order. Guard-second would answer "already has an unresolved write
    /// session" — true, but not the truer fact: a sealed volume is not a
    /// write target at all, and telling the operator to `volume resume` it
    /// would point them at a dead end (ADR-0003: never written again).
    #[test]
    fn volume_write_refuses_by_status_before_the_unresolved_session_check() {
        let (conn, _tenant_id, stage_set_id) = escrow_check_fixture();
        let snapshot_id: i64 = conn
            .query_row(
                "SELECT snapshot_id FROM stage_sets WHERE id = ?1",
                params![stage_set_id],
                |r| r.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                  capacity_bytes, status)
             VALUES ('L6-BOTH', 'lto', 'lto0', 'LTO-6', 2500000000000, 'sealed')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();

        // `planned`/`in_progress`/`interrupted` are what the session check
        // counts as unresolved (see `volume_write`); `interrupted` is the one
        // an operator would actually meet.
        conn.execute(
            "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
             VALUES (?1, ?2, ?3, 'interrupted')",
            params![stage_set_id, snapshot_id, volume_id],
        )
        .unwrap();

        let tmp = tempfile::TempDir::new().unwrap();
        let paths = TapectlPaths::new(tmp.path().join("home"));
        let config = Config::default();

        let err = volume_write(
            &conn,
            &paths,
            &config,
            "L6-BOTH",
            "/nonexistent/tapectl-order-test-nst",
            512 * 1024,
            false,
            false,
            false,
            false, // --full-confirm
            true,
        )
        .unwrap_err();

        assert!(
            matches!(err, TapectlError::VolumeNotWriteTarget { ref status, .. } if status == "sealed"),
            "the status guard must win over the unresolved-session check, got: {err}"
        );
        let msg = format!("{err}");
        assert!(
            !msg.contains("unresolved write session"),
            "guard ran second — the session check answered first: {msg}"
        );
    }

    #[test]
    fn record_write_bookkeeping_sums_only_padded_slice_entries() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, capacity_bytes, status)
             VALUES ('BKTEST', 'lto', 'lto0', 1000000, 'active')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();

        let bs = 512 * 1024u64;
        let layout = Layout {
            label: "BKTEST".to_string(),
            volume_uuid: "u".to_string(),
            media_type: "LTO-6".to_string(),
            block_size: bs,
            budget: CapacityBudget {
                available_bytes: 0,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![
                LayoutEntry {
                    position: 0,
                    kind: ZoneKind::IdThunk,
                    size_bytes: Some(100),
                    sha256: None,
                    source: ContentSource::Generated,
                },
                // 1 byte pads to one whole block.
                LayoutEntry {
                    position: 1,
                    kind: ZoneKind::Slice { stage_slice_id: 1 },
                    size_bytes: Some(1),
                    sha256: None,
                    source: ContentSource::Generated,
                },
                // block_size + 1 pads to two whole blocks.
                LayoutEntry {
                    position: 2,
                    kind: ZoneKind::Slice { stage_slice_id: 2 },
                    size_bytes: Some(bs + 1),
                    sha256: None,
                    source: ContentSource::Generated,
                },
            ],
        };

        record_write_bookkeeping(&conn, volume_id, &layout, bs).unwrap();

        let (bytes_written, num_data_files, has_manifest): (i64, i64, i64) = conn
            .query_row(
                "SELECT bytes_written, num_data_files, has_manifest FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();

        assert_eq!(
            num_data_files, 2,
            "only Slice entries count toward num_data_files, not id_thunk"
        );
        assert_eq!(
            bytes_written,
            (bs + 2 * bs) as i64,
            "must sum block-PADDED (on-tape) slice bytes, not the true size_bytes"
        );
        assert_eq!(has_manifest, 1);

        // #420: on a short-sealed volume the figures are the tape's — only
        // the slices at or before `ended_after` are on it.
        conn.execute(
            "UPDATE volumes SET ended_after = 1, bytes_written = 0, num_data_files = 0
             WHERE id = ?1",
            params![volume_id],
        )
        .unwrap();
        record_write_bookkeeping(&conn, volume_id, &layout, bs).unwrap();
        let (bytes_written, num_data_files): (i64, i64) = conn
            .query_row(
                "SELECT bytes_written, num_data_files FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            (bytes_written, num_data_files),
            (bs as i64, 1),
            "the slice after ended_after is not on the tape"
        );
    }

    /// Issue #386's progress total for a full readback, on a short tape
    /// (#420): the files at or before `ended_after` and the seal — not the
    /// plan's every file. A full seal (`None`) counts the whole plan.
    #[test]
    fn a_short_tapes_readback_total_counts_what_the_walk_reads() {
        let bs = 4096u64;
        let entry = |position: i32, kind: ZoneKind, size: u64| LayoutEntry {
            position,
            kind,
            size_bytes: Some(size),
            sha256: None,
            source: ContentSource::Generated,
        };
        let layout = Layout {
            label: "RB".into(),
            volume_uuid: "u".into(),
            media_type: "LTO-6".into(),
            block_size: bs,
            budget: CapacityBudget {
                available_bytes: 0,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![
                entry(0, ZoneKind::IdThunk, 100),
                entry(1, ZoneKind::Slice { stage_slice_id: 1 }, 2 * bs),
                entry(2, ZoneKind::Slice { stage_slice_id: 2 }, 3 * bs),
                entry(3, ZoneKind::Slice { stage_slice_id: 3 }, 5 * bs),
                entry(4, ZoneKind::SealMarker, 10),
            ],
        };
        assert_eq!(readback_bytes(&layout, None), Some(12 * bs));
        // Sealed short after file 1: files 0 and 1, and the seal.
        assert_eq!(readback_bytes(&layout, Some(1)), Some(4 * bs));
        // After file 2: files 0 to 2, and the seal.
        assert_eq!(readback_bytes(&layout, Some(2)), Some(7 * bs));
    }

    /// Issue #392: `first_write` was stamped when the write session
    /// FINISHED, the same instant as `last_write`. It is when the volume's
    /// first write began (`writes.started_at`); `last_write` stays the
    /// completion.
    #[test]
    fn record_write_bookkeeping_dates_first_write_from_when_the_write_began() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute_batch(
            "INSERT INTO tenants (name, is_operator, status) VALUES ('t', 0, 'active');
             INSERT INTO units (uuid, name, tenant_id, checksum_mode, encrypt, status)
                 VALUES ('u', 'unit', 1, 'mtime_size', 1, 'active');
             INSERT INTO snapshots (unit_id, version, snapshot_type, status, source_path)
                 VALUES (1, 1, 'full', 'current', '/x');
             INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (1, 'staged', 1);
             INSERT INTO volumes (label, backend_type, backend_name, capacity_bytes, status)
                 VALUES ('BKTEST3', 'lto', 'lto0', 1000000, 'sealed');
             INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status, started_at)
                 VALUES (1, 1, 1, 'completed', '2026-10-01 02:53:12');",
        )
        .unwrap();
        let layout = Layout {
            label: "BKTEST3".to_string(),
            volume_uuid: "u".to_string(),
            media_type: "LTO-6".to_string(),
            block_size: 4096,
            budget: CapacityBudget {
                available_bytes: 0,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![],
        };
        record_write_bookkeeping(&conn, 1, &layout, 4096).unwrap();
        let (first, last): (String, String) = conn
            .query_row(
                "SELECT first_write, last_write FROM volumes WHERE id = 1",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(first, "2026-10-01 02:53:12");
        assert_ne!(last, first, "last_write is the completion, stamped now");
    }

    /// ADR-0012 2026-10-07 item 33: a catalog error recording what followed
    /// a sealed, confirmed copy does not fail the write. It comes back as
    /// the warning that names the step, and the write exits 0. With the
    /// catalog writable the same call records both and warns nothing.
    #[test]
    fn a_catalog_error_after_the_seal_is_a_warning_not_an_error() {
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, capacity_bytes, status)
             VALUES ('BKWARN', 'lto', 'lto0', 1000000, 'sealed')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        let layout = Layout {
            label: "BKWARN".to_string(),
            volume_uuid: "u".to_string(),
            media_type: "LTO-6".to_string(),
            block_size: 4096,
            budget: CapacityBudget {
                available_bytes: 0,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![],
        };

        conn.execute_batch("PRAGMA query_only = ON").unwrap();
        let warning = record_after_sealed(
            &conn,
            volume_id,
            "BKWARN",
            &layout,
            4096,
            &full_seal(volume_id, "BKWARN"),
        )
        .expect("a read-only catalog cannot record, and says so");
        assert!(
            warning.starts_with(
                "warning: volume \"BKWARN\" is sealed and confirmed and counts as a copy, but \
                 recording its write figures"
            ),
            "{warning}"
        );
        assert!(warning.contains("write_completed event"), "{warning}");
        assert!(warning.contains("The tape needs nothing."), "{warning}");

        conn.execute_batch("PRAGMA query_only = OFF").unwrap();
        assert_eq!(
            record_after_sealed(
                &conn,
                volume_id,
                "BKWARN",
                &layout,
                4096,
                &full_seal(volume_id, "BKWARN")
            ),
            None
        );
        let (has_manifest, events): (i64, i64) = conn
            .query_row(
                "SELECT has_manifest,
                        (SELECT COUNT(*) FROM events WHERE action = 'write_completed')
                 FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!((has_manifest, events), (1, 1));
    }

    /// The confirm's sealed arm records through [`record_after_sealed`],
    /// whose failure is a warning — never with a `?` that would turn it
    /// into an exit-2 error again.
    #[test]
    fn finish_confirm_records_through_the_warning_path() {
        const SRC: &str = include_str!("write.rs");
        let f = "fn finish_confirm(";
        let start = SRC.find(f).unwrap();
        let end = SRC[start..].find("\n}\n").unwrap() + start;
        let body = &SRC[start..end];
        assert!(
            !body[f.len()..].contains("\nfn "),
            "overran into another fn"
        );
        assert!(body.contains("record_after_sealed("), "{body}");
        assert!(!body.contains("record_write_bookkeeping("), "{body}");
    }

    #[test]
    fn record_write_bookkeeping_never_touches_status() {
        // confirm()'s own transaction already set status = 'sealed' before
        // this runs (session::SealedPending::confirm) — this bookkeeping
        // step must not clobber it back to some other value.
        let conn = crate::db::open_memory().unwrap();
        conn.execute(
            "INSERT INTO volumes (label, backend_type, backend_name, capacity_bytes, status)
             VALUES ('BKTEST2', 'lto', 'lto0', 1000000, 'sealed')",
            [],
        )
        .unwrap();
        let volume_id = conn.last_insert_rowid();
        let layout = Layout {
            label: "BKTEST2".to_string(),
            volume_uuid: "u".to_string(),
            media_type: "LTO-6".to_string(),
            block_size: 4096,
            budget: CapacityBudget {
                available_bytes: 0,
                reserve_bytes: 0,
                plan_bound_bytes: None,
                span_tail_from: None,
            },
            entries: vec![],
        };
        record_write_bookkeeping(&conn, volume_id, &layout, 4096).unwrap();
        let status: String = conn
            .query_row(
                "SELECT status FROM volumes WHERE id = ?1",
                params![volume_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(status, "sealed");
    }

    /// Issue #357: an operator reads this line (it is the quarantine error
    /// and the `write_quarantined` event), so the tier and every mismatch
    /// are rendered in words — never Rust's `{:?}` of `Tier`/`Mismatch`.
    #[test]
    fn describe_quarantine_confirm_failed_renders_tier_and_mismatches_in_words() {
        let evidence = Evidence {
            tier: Tier::Integrity,
            files_checked: 5,
            mismatches: vec![
                Mismatch {
                    position: 4,
                    kind: MismatchKind::ContentHashMismatch,
                    expected: "aa".into(),
                    actual: "bb".into(),
                },
                Mismatch {
                    position: 6,
                    kind: MismatchKind::NavigationDisagreement,
                    expected: "front index lists position 6".into(),
                    actual: "missing from front index".into(),
                },
            ],
        };
        let msg = describe_quarantine(&QuarantineReason::ConfirmFailed(evidence));
        assert!(msg.contains("2 mismatch"), "the mismatch count: {msg}");
        assert!(msg.contains("full read-back"), "the tier, in words: {msg}");
        assert!(
            msg.contains("position 4: content_hash_mismatch — expected aa, found bb"),
            "the first mismatch, in `volume verify`'s own shape: {msg}"
        );
        assert!(
            msg.contains("position 6: navigation_disagreement"),
            "every mismatch is named: {msg}"
        );
        for debug in [
            "Integrity",
            "Mismatch {",
            "MismatchKind",
            "ContentHashMismatch",
            "[",
            "{",
        ] {
            assert!(
                !msg.contains(debug),
                "Debug output {debug:?} leaked into: {msg}"
            );
        }

        let quick = describe_quarantine(&QuarantineReason::ConfirmFailed(Evidence {
            tier: Tier::Navigable,
            files_checked: 1,
            mismatches: vec![Mismatch {
                position: 3,
                kind: MismatchKind::FrontIndexUnreadable,
                expected: "readable".into(),
                actual: "short read".into(),
            }],
        }));
        assert!(quick.contains("1 mismatch"), "{quick}");
        assert!(quick.contains("quick navigation check"), "{quick}");
        assert!(!quick.contains("Navigable"), "{quick}");
    }

    /// Issue #357: the resume-side identity mismatch names what File 0 said
    /// in words, not as `Some(IdThunkIdentity { .. })`.
