        /// A `MemStore` that has a signal arrive once the readback after the
        /// seal has read position 4 (the first file after File 3).
        struct StopAfterFour {
            inner: MemStore,
        }

        impl Store for StopAfterFour {
            fn capacity(&mut self) -> Result<crate::store::CapacityReport> {
                self.inner.capacity()
            }
            fn execute(
                &mut self,
                src: &mut dyn std::io::Read,
                len: u64,
                sync: bool,
            ) -> Result<u64> {
                self.inner.execute(src, len, sync)
            }
            fn read_file(&mut self, position: u32, sink: &mut dyn std::io::Write) -> Result<u64> {
                let r = self.inner.read_file(position, sink);
                if position == 4 && self.inner.files.len() > 5 {
                    crate::signal::interrupt_this_thread(true);
                }
                r
            }
            fn reposition_for_resume(&mut self, file_index: u32) -> Result<()> {
                self.inner.reposition_for_resume(file_index)
            }
            // A fresh write's contact asks whether an unreadable File 0 is
            // a blank tape (issue #400); the answer is the inner store's.
            fn blank_at_bot(&mut self) -> Result<bool> {
                self.inner.blank_at_bot()
            }
        }

        /// Issue #410: a full confirm stopped by a signal keeps what it read
        /// back clean, and its error tells the operator to resume WITH
        /// `--full-confirm` — without it the resume runs the quick confirm
        /// and the readback is not continued.
        #[test]
        fn an_interrupted_full_confirm_says_how_to_continue_it() {
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, volume_id) = swept_write_fixture("SW-STOP", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let mut slot = ContactSlot::empty();
            let mut store = StopAfterFour {
                inner: MemStore::new(512 * 1024),
            };

            let r = volume_write_contacted(
                &conn,
                &paths,
                &config,
                "SW-STOP",
                GENCHK_DEVICE,
                512 * 1024,
                false,
                false,
                false,
                true, // --full-confirm
                true,
                &mut slot,
                ContactStore::Injected(&mut store),
                None,
            );
            crate::signal::interrupt_this_thread(false);
            let err = slot.finish_result(r).expect_err("the confirm stops");
            let msg = err.to_string();
            assert!(matches!(err, TapectlError::WriteInterrupted(_)), "{msg}");
            assert!(
                msg.contains("volume resume SW-STOP --full-confirm"),
                "names the flag that continues the readback: {msg}"
            );
            let checkpoints: Vec<u32> = conn
                .prepare(
                    "SELECT rc.position FROM readback_checkpoints rc
                     JOIN verification_sessions vs ON vs.id = rc.session_id
                     WHERE vs.volume_id = ?1 ORDER BY rc.position",
                )
                .unwrap()
                .query_map(params![volume_id], |r| r.get(0))
                .unwrap()
                .collect::<rusqlite::Result<_>>()
                .unwrap();
            assert_eq!(checkpoints, vec![0, 1, 2, 4]);
        }

        /// ADR-0012 2026-10-06 item 4 (issue #370): the filtered
        /// `catalog.db` a write puts in its operator envelopes is plaintext
        /// (paths, sizes, hashes), so it is built in the tapectl home and
        /// removed once the envelopes are built — never under staging, where
        /// it used to sit in the session directory until `staging clean`.
        #[test]
        fn a_write_builds_its_catalog_database_outside_staging() {
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, volume_id) = swept_write_fixture("SW-NODB", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            let staging = tmp.path().join("staging");
            fs::create_dir_all(&staging).unwrap();
            config.staging.directory = staging.to_string_lossy().into_owned();
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let mut slot = ContactSlot::empty();
            let mut store = MemStore::new(512 * 1024);

            let r = volume_write_contacted(
                &conn,
                &paths,
                &config,
                "SW-NODB",
                GENCHK_DEVICE,
                512 * 1024,
                false,
                false,
                false,
                false, // --full-confirm
                true,
                &mut slot,
                ContactStore::Injected(&mut store),
                None,
            );
            slot.finish_result(r)
                .expect("a write to a blank MemStore completes");
            let status: String = conn
                .query_row(
                    "SELECT status FROM volumes WHERE id = ?1",
                    params![volume_id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(status, "sealed", "positive control: the write completed");

            let files: Vec<PathBuf> = walkdir::WalkDir::new(&staging)
                .into_iter()
                .flatten()
                .filter(|e| e.file_type().is_file())
                .map(|e| e.into_path())
                .collect();
            assert!(
                files
                    .iter()
                    .any(|f| f.to_string_lossy().contains("/sessions/")),
                "positive control: the session's files are under staging: {files:?}"
            );
            let dbs: Vec<&PathBuf> = files
                .iter()
                .filter(|f| f.extension().is_some_and(|e| e == "db"))
                .collect();
            assert!(dbs.is_empty(), "no database under staging: {dbs:?}");
            let left: Vec<PathBuf> = walkdir::WalkDir::new(&paths.home)
                .into_iter()
                .flatten()
                .filter(|e| e.file_type().is_file())
                .map(|e| e.into_path())
                .filter(|p| p.to_string_lossy().contains("catalog_snapshot"))
                .collect();
            assert!(left.is_empty(), "the home's copy is removed: {left:?}");
        }

        /// One `volume write` of `label` over `store`, as the CLI runs it.
        fn write_once(
            conn: &Connection,
            config: &Config,
            paths: &TapectlPaths,
            label: &str,
            store: &mut dyn Store,
        ) -> Result<()> {
            use crate::tape::log_pages::tests::FixtureSource;
            let src = std::cell::RefCell::new(FixtureSource::default());
            let mut slot = ContactSlot::empty()
                .with_drive_identity(identity_with_serial(Some("XYZZY_A1")))
                .with_log_source(&src);
            let r = volume_write_contacted(
                conn,
                paths,
                config,
                label,
                GENCHK_DEVICE,
                512 * 1024,
                false,
                false,
                false,
                false, // --full-confirm
                true,
                &mut slot,
                ContactStore::Injected(store),
                None,
            );
            slot.finish_result(r).map(|_| ())
        }

        /// Issue #401, through `volume write` itself: a write aborted by
        /// tri-layer L2 (a staged slice that rotted in place, same size) is
        /// followed, once the slice is right again, by a second `volume
        /// write` of the same label on the same cartridge — and that one
        /// seals. It used to fail at `plan` with a raw `UNIQUE constraint
        /// failed`, which is what the abort message and the troubleshooting
        /// guide both told the operator to run.
        #[test]
        fn a_write_aborted_by_l2_is_written_again_and_seals() {
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, volume_id) = swept_write_fixture("SW-AGAIN", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let slice = tmp.path().join("slices").join("slice_1.age");
            let good = fs::read(&slice).unwrap();
            let mut rotted = good.clone();
            rotted[0] ^= 0xff;
            fs::write(&slice, &rotted).unwrap();

            let mut store = MemStore::new(512 * 1024);
            let err = write_once(&conn, &config, &paths, "SW-AGAIN", &mut store)
                .unwrap_err()
                .to_string();
            assert!(
                err.contains("hash mismatch"),
                "positive control: L2 aborted: {err}"
            );

            fs::write(&slice, &good).unwrap();
            write_once(&conn, &config, &paths, "SW-AGAIN", &mut store)
                .expect("issue #401: the second `volume write` of the label seals");
            let status: String = conn
                .query_row(
                    "SELECT status FROM volumes WHERE id = ?1",
                    params![volume_id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(status, "sealed");
            let rows: Vec<String> = conn
                .prepare("SELECT status FROM writes WHERE volume_id = ?1")
                .unwrap()
                .query_map(params![volume_id], |r| r.get(0))
                .unwrap()
                .collect::<rusqlite::Result<_>>()
                .unwrap();
            assert_eq!(rows, vec!["completed"]);
        }

        /// Issue #400, through `volume write` itself over the real
        /// `TapeStore`: the loaded cartridge holds a recording (three files)
        /// whose File 0 the drive cannot read. That used to be taken as a
        /// blank tape and written over from BOT; now the write is refused
        /// before the tape moves forward a single write, and nothing is
        /// planned.
        #[test]
        fn a_write_refuses_an_unreadable_file_zero_on_a_tape_not_provably_blank() {
            use crate::tape::fake::{FakeTape, Op};
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, _volume_id) = swept_write_fixture("SW-EIO", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let fake = FakeTape::with_files(vec![vec![7u8; 512 * 1024]; 3], 512 * 1024);
            fake.state().unreadable.push(0);
            let mut store = crate::store::TapeStore::from_ops(fake.boxed(), u64::MAX).unwrap();

            let err = write_once(&conn, &config, &paths, "SW-EIO", &mut store)
                .unwrap_err()
                .to_string();
            assert!(
                err.contains("could not be read") && err.contains("--force"),
                "{err}"
            );
            assert!(
                !fake.ops().iter().any(|op| matches!(op, Op::Write(_))),
                "nothing written: {:?}",
                fake.ops()
            );
            let planned: i64 = conn
                .query_row("SELECT COUNT(*) FROM writes", [], |r| r.get(0))
                .unwrap();
            assert_eq!(planned, 0);
        }

        /// Issue #401, the end-of-tape case through `volume write`: the
        /// medium runs out, and a second `volume write` of the label on the
        /// same cartridge (here: the same recorded files, with room) seals.
        #[test]
        fn a_write_aborted_at_end_of_tape_is_written_again_and_seals() {
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, volume_id) = swept_write_fixture("SW-EOT", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            let paths = TapectlPaths::new(tmp.path().join("home"));

            let mut short = MemStore::new(512 * 1024).with_enospc_after(2 * 512 * 1024);
            let err = write_once(&conn, &config, &paths, "SW-EOT", &mut short)
                .unwrap_err()
                .to_string();
            assert!(
                err.contains("aborted"),
                "positive control: the write aborted: {err}"
            );

            let mut store = MemStore::new(512 * 1024);
            store.files = short.files.clone();
            store.syncs = short.syncs.clone();
            write_once(&conn, &config, &paths, "SW-EOT", &mut store)
                .expect("issue #401: the second `volume write` of the label seals");
            let status: String = conn
                .query_row(
                    "SELECT status FROM volumes WHERE id = ?1",
                    params![volume_id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(status, "sealed");
        }

        // ── ADR-0012, 2026-10-07 item 20 (issue #408): the write family's
        //    exit table, one outcome at a time, through `volume write`
        //    itself over an injected store ──

        /// A fault one test injects into a [`Faulty`] store.
        #[derive(Clone, Copy)]
        enum Fault {
            /// Every write fails with a drive error (not ENOSPC).
            WriteIo,
            /// The seal's write (the one synchronous filemark) fails with a
            /// drive error; every other write lands.
            SealIo,
            /// The seal's write fails as a full medium (#420, §4.3 W6: the
            /// hard end inside the seal, or its filemark refused); every
            /// other write lands.
            SealFull,
            /// Reading File 3 back fails with a drive error.
            ReadFrontIndexIo,
            /// Reading File 3 back returns different bytes from those
            /// written.
            ReadFrontIndexCorrupt,
            /// Reading a file after File 3 back returns only its first few
            /// bytes: a short read, which proves nothing about the medium
            /// (an `Inconclusive` confirm, not a quarantine).
            ReadContentShort,
            /// A signal arrives once the seal's write has landed, before the
            /// confirm begins.
            SignalAfterSeal,
        }

        /// A `MemStore` with one [`Fault`].
        struct Faulty {
            inner: MemStore,
            fault: Fault,
        }

        impl Store for Faulty {
            fn capacity(&mut self) -> Result<crate::store::CapacityReport> {
                self.inner.capacity()
            }
            fn execute(
                &mut self,
                src: &mut dyn std::io::Read,
                len: u64,
                sync: bool,
            ) -> Result<u64> {
                match self.fault {
                    Fault::WriteIo => Err(TapectlError::TapeIo("injected write error".into())),
                    Fault::SealIo if sync => {
                        Err(TapectlError::TapeIo("injected seal write error".into()))
                    }
                    Fault::SealFull if sync => Err(TapectlError::MediumFull(
                        "write: No space left on device (os error 28)".into(),
                    )),
                    Fault::SignalAfterSeal if sync => {
                        let written = self.inner.execute(src, len, sync);
                        crate::signal::interrupt_this_thread(true);
                        written
                    }
                    _ => self.inner.execute(src, len, sync),
                }
            }
            fn read_file(&mut self, position: u32, sink: &mut dyn std::io::Write) -> Result<u64> {
                let sealed = self.inner.syncs.last() == Some(&true);
                match self.fault {
                    Fault::ReadFrontIndexIo if sealed && position == 3 => {
                        Err(TapectlError::TapeIo("injected read error".into()))
                    }
                    Fault::ReadFrontIndexCorrupt if sealed && position == 3 => {
                        let mut bytes = Vec::new();
                        let n = self.inner.read_file(position, &mut bytes)?;
                        bytes[0] ^= 0xff;
                        sink.write_all(&bytes)?;
                        Ok(n)
                    }
                    Fault::ReadContentShort if sealed && position > 3 => {
                        let mut bytes = Vec::new();
                        self.inner.read_file(position, &mut bytes)?;
                        bytes.truncate(5);
                        sink.write_all(&bytes)?;
                        Ok(bytes.len() as u64)
                    }
                    _ => self.inner.read_file(position, sink),
                }
            }
            fn reposition_for_resume(&mut self, file_index: u32) -> Result<()> {
                self.inner.reposition_for_resume(file_index)
            }
            fn blank_at_bot(&mut self) -> Result<bool> {
                self.inner.blank_at_bot()
            }
        }

        /// One `volume write` of a fresh fixture over `store`, returning
        /// the result and the outcome `main` would exit with.
        fn write_outcome(
            label: &str,
            store: &mut dyn Store,
            prewrite_hash: bool,
        ) -> (Result<()>, i32) {
            write_outcome_with(label, store, prewrite_hash, false, |_| {})
        }

        /// [`write_outcome`] with `--full-confirm` chosen and a hook that
        /// prepares the catalog connection before the write.
        fn write_outcome_with(
            label: &str,
            store: &mut dyn Store,
            prewrite_hash: bool,
            full_confirm: bool,
            prepare: impl FnOnce(&Connection),
        ) -> (Result<()>, i32) {
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, _volume_id) = swept_write_fixture(label, tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());
            prepare(&conn);
            let paths = TapectlPaths::new(tmp.path().join("home"));
            let mut slot = ContactSlot::empty();
            let r = volume_write_contacted(
                &conn,
                &paths,
                &config,
                label,
                GENCHK_DEVICE,
                512 * 1024,
                false,
                false,
                prewrite_hash,
                full_confirm,
                true,
                &mut slot,
                ContactStore::Injected(store),
                None,
            );
            let r = slot.finish_result(r).map(|_| ());
            let code = match &r {
                Ok(()) => crate::error::EXIT_SUCCESS,
                Err(e) => crate::error::ErrorContract::Write.exit_code(&clone_error(e).into()),
            };
            (r, code)
        }

        /// The library error, rebuilt for an `anyhow::Error` (it is not
        /// `Clone`): the variant decides the code, the text is kept.
        fn clone_error(e: &TapectlError) -> TapectlError {
            let text = e.to_string();
            match e {
                TapectlError::WriteInterrupted(_) => TapectlError::WriteInterrupted(text),
                TapectlError::WriteAborted(_) => TapectlError::WriteAborted(text),
                TapectlError::WriteQuarantined(_) => TapectlError::WriteQuarantined(text),
                TapectlError::ConfirmInconclusive(_) => TapectlError::ConfirmInconclusive(text),
                TapectlError::CatalogBusy(_) => TapectlError::CatalogBusy(text),
                _ => TapectlError::Other(text),
            }
        }

        /// 0: sealed and confirmed.
        #[test]
        fn exit_0_a_write_that_seals_and_confirms() {
            let (r, code) = write_outcome("EX-0", &mut MemStore::new(512 * 1024), false);
            r.expect("seals");
            assert_eq!(code, 0);
        }

        /// #418 R4, through the real write path: the cross-volume index
        /// (`volume-format-v2.md` §1.5) reaches the envelopes - this tape and
        /// the other sealed one the catalog holds, in the operator's map and
        /// in the tenant's own, with the tenant's paths - and none of it, nor
        /// any path of the archive, is ever in the clear under staging; the
        /// work directory it was built in is gone when the write is.
        #[test]
        fn a_volume_write_puts_the_cross_volume_index_in_the_envelopes_and_none_of_it_under_staging(
        ) {
            use crate::volume::{envelope, format, index};
            const NEEDLE: &str = "idx-needle-q7x2k.jpg";
            let tmp = tempfile::TempDir::new().unwrap();
            let (conn, mut config, _volume_id) = swept_write_fixture("IDX-1", tmp.path());
            config.backends.lto[0].capacity_override = Some("2400G".into());

            // Keys this test holds: the fixture registers public halves only.
            let op = crate::crypto::keys::generate_keypair();
            let alpha = crate::crypto::keys::generate_keypair();
            for (alias, kp) in [("operator-key", &op), ("alpha-key", &alpha)] {
                conn.execute(
                    "UPDATE encryption_keys SET public_key = ?1, fingerprint = ?2 WHERE alias = ?3",
                    params![kp.public_key, kp.fingerprint, alias],
                )
                .unwrap();
            }
            // The version this write carries has a path; the unit has a later
            // version, current, on another sealed tape.
            let (unit_id, snapshot_id): (i64, i64) = conn
                .query_row("SELECT unit_id, id FROM snapshots", [], |r| {
                    Ok((r.get(0)?, r.get(1)?))
                })
                .unwrap();
            crate::db::files::insert_version(
                &conn,
                snapshot_id,
                [Ok(crate::db::files::FileEntry {
                    path: NEEDLE.to_string(),
                    kind: crate::db::files::FileKind::Regular,
                    size_bytes: 1234,
                    mtime_ns: None,
                    sha256: None,
                    link_target: None,
                })],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO volumes (label, backend_type, backend_name, media_type,
                                      capacity_bytes, status, uuid, sealed_at)
                 VALUES ('IDX-HIST', 'lto', 'lto0', 'LTO-6', 2500000000000, 'sealed',
                         'hist-uuid', '2026-09-01 12:00:00')",
                [],
            )
            .unwrap();
            let hist_volume = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO snapshots (unit_id, version, status, source_path)
                 VALUES (?1, 2, 'current', '/hist')",
                params![unit_id],
            )
            .unwrap();
            let hist_snapshot = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO stage_sets (snapshot_id, status, slice_size) VALUES (?1, 'cleaned', 1)",
                params![hist_snapshot],
            )
            .unwrap();
            let hist_set = conn.last_insert_rowid();
            conn.execute(
                "INSERT INTO writes (stage_set_id, snapshot_id, volume_id, status)
                 VALUES (?1, ?2, ?3, 'completed')",
                params![hist_set, hist_snapshot, hist_volume],
            )
            .unwrap();

            let paths = TapectlPaths::new(tmp.path().join("home"));
            let mut store = MemStore::new(512 * 1024);
            let mut slot = ContactSlot::empty();
            let r = volume_write_contacted(
                &conn,
                &paths,
                &config,
                "IDX-1",
                GENCHK_DEVICE,
                512 * 1024,
                false,
                false,
                false,
                false,
                true,
                &mut slot,
                ContactStore::Injected(&mut store),
                None,
            );
            slot.finish_result(r).expect("the write seals");

            // Staging holds no plaintext of the index: no tsv by name, no
            // header, no path. The positive controls: it holds the session
            // directory's files, and the same scan finds a planted path.
            let scan = |dir: &std::path::Path| -> (usize, Vec<String>) {
                let (mut seen, mut bad) = (0, Vec::new());
                let mut stack = vec![dir.to_path_buf()];
                while let Some(d) = stack.pop() {
                    for entry in std::fs::read_dir(&d).unwrap() {
                        let path = entry.unwrap().path();
                        if path.is_dir() {
                            stack.push(path);
                            continue;
                        }
                        seen += 1;
                        let bytes = std::fs::read(&path).unwrap();
                        let has = |n: &str| bytes.windows(n.len()).any(|w| w == n.as_bytes());
                        if path.extension().is_some_and(|e| e == "tsv")
                            || has(NEEDLE)
                            || has(&index::PATHS_COLUMNS.join("\t"))
                            || has(&index::UNITS_COLUMNS.join("\t"))
                        {
                            bad.push(path.display().to_string());
                        }
                    }
                }
                (seen, bad)
            };
            let staging = std::path::Path::new(&config.staging.directory);
            let (seen, bad) = scan(staging);
            assert!(
                seen >= 8,
                "the scan reached the session's files: saw {seen}"
            );
            assert!(bad.is_empty(), "plaintext under staging: {bad:?}");
            let control = tmp.path().join("control");
            std::fs::create_dir_all(&control).unwrap();
            std::fs::write(control.join("x"), format!("row\t{NEEDLE}\n")).unwrap();
            assert_eq!(scan(&control).1.len(), 1, "the scan finds a planted path");
            // And the tapectl home's work directory was removed with the write.
            let left: Vec<_> = std::fs::read_dir(paths.home.join("tmp"))
                .unwrap()
                .map(|e| e.unwrap().file_name())
                .collect();
            assert!(left.is_empty(), "work directory left behind: {left:?}");

            // On the tape: the operator envelope's map, read back by the
            // rebuild's own reader.
            let fi = crate::store::read_small_bytes(&mut store, 3, "front index").unwrap();
            let entries = format::parse_front_index(&String::from_utf8_lossy(&fi)).unwrap();
            let entry = |kind: &str| {
                entries
                    .iter()
                    .find(|e| e.type_label == kind)
                    .unwrap_or_else(|| panic!("no {kind}"))
                    .clone()
            };
            let op_id: age::x25519::Identity = op.secret_key.parse().unwrap();
            let scratch = tempfile::TempDir::new().unwrap();
            let opened = envelope::open_envelope(
                &mut store,
                &entry("operator_envelope"),
                &[op_id],
                scratch.path(),
            )
            .expect("the operator envelope opens");
            let map =
                std::fs::read_to_string(opened.index_units.expect("the operator map")).unwrap();
            let rows = index::parse_units(&map).unwrap();
            let key = |r: &index::UnitsRow| (r.volume.clone(), r.version, r.state.clone());
            assert_eq!(
                rows.iter().map(key).collect::<Vec<_>>(),
                vec![
                    ("IDX-1".to_string(), 1, "this-tape".to_string()),
                    ("IDX-HIST".to_string(), 2, "sealed".to_string()),
                ]
            );
            assert!(rows
                .iter()
                .all(|r| r.tenant == "alpha" && r.unit == "photos"));

            // The tenant's own envelope, with its key: units and paths.
            let tenant = entry("tenant_envelope");
            let mut bytes = Vec::new();
            store.read_file(tenant.position as u32, &mut bytes).unwrap();
            bytes.truncate(tenant.size_bytes.unwrap() as usize);
            let alpha_id: age::x25519::Identity = alpha.secret_key.parse().unwrap();
            let reader = age::Decryptor::new(&bytes[..])
                .unwrap()
                .decrypt(std::iter::once(&alpha_id as &dyn age::Identity))
                .unwrap();
            let mut members = std::collections::BTreeMap::new();
            for m in tar::Archive::new(reader).entries().unwrap() {
                let mut m = m.unwrap();
                let name = m.path().unwrap().to_string_lossy().to_string();
                let mut text = String::new();
                std::io::Read::read_to_string(&mut m, &mut text).unwrap_or(0);
                members.insert(name, text);
            }
            assert!(
                members["index/units.tsv"].contains("IDX-HIST"),
                "{members:?}"
            );
            let paths_rows = index::parse_paths(&members["index/paths.tsv"]).unwrap();
            assert_eq!(
                paths_rows.iter().map(|r| (r.version, r.path.as_str())).collect::<Vec<_>>(),
                vec![(1, NEEDLE)],
                "this write's version has its path; the later version on IDX-HIST has none recorded"
            );
        }

        /// 2: refused before anything was written — the loaded tape is
        /// another volume's (the File 0 check), and a signal during the
        /// pre-write hash. Neither leaves a session to resume.
        #[test]
        fn exit_2_a_write_refused_before_the_tape_moved() {
            let mut foreign = MemStore::new(512 * 1024);
            fw_put_file(
                &mut foreign,
                0,
                fw_id_thunk_bytes("OTHER", "00000000-0000-0000-0000-000000000000", 8),
            );
            let (r, code) = write_outcome("EX-2A", &mut foreign, false);
            assert!(r.is_err(), "positive control: refused");
            assert_eq!(code, 2, "{}", r.unwrap_err());

            crate::signal::interrupt_this_thread(true);
            let (r, code) = write_outcome("EX-2B", &mut MemStore::new(512 * 1024), true);
            crate::signal::interrupt_this_thread(false);
            let err = r.unwrap_err();
            assert!(err.to_string().contains("nothing was written"), "{err}");
            assert_eq!(code, 2, "{err}");
        }

        /// 3: the seal is on the tape and the confirm's readback failed on
        /// the drive, proving nothing about the medium.
        #[test]
        fn exit_3_a_confirm_that_reached_no_verdict() {
            let mut store = Faulty {
                inner: MemStore::new(512 * 1024),
                fault: Fault::ReadFrontIndexIo,
            };
            let (r, code) = write_outcome("EX-3", &mut store, false);
            let err = r.unwrap_err();
            assert!(
                matches!(err, TapectlError::ConfirmInconclusive(_)),
                "{err:?}"
            );
            assert_eq!(code, 3, "{err}");
        }

        /// 4: a drive error mid-write, and the seal's own write failing —
        /// both leave a session `volume resume` continues.
        #[test]
        fn exit_4_a_write_stopped_part_way_is_resumable() {
            for fault in [Fault::WriteIo, Fault::SealIo] {
                let mut store = Faulty {
                    inner: MemStore::new(512 * 1024),
                    fault,
                };
                let (r, code) = write_outcome("EX-4", &mut store, false);
                let err = r.unwrap_err();
                assert!(matches!(err, TapectlError::WriteInterrupted(_)), "{err:?}");
                assert!(err.to_string().contains("volume resume EX-4"), "{err}");
                assert_eq!(code, 4, "{err}");
            }
        }

        /// 4, through a signal: the full confirm stopped between files.
